INSERT INTO public.cbq_cases (id, part, section, title, narrative, exhibits, difficulty, source, verified, active) VALUES ('f55bae99-9406-50ae-afd8-12781c0ce311', 'Part 2', 'Decision Analysis', 'Thrissur Agro Foods — make-or-buy on a constrained shelling line', 'Thrissur Agro Foods roasts and packs branded cashews. The packing division currently buys roasted, shelled cashews from an outside processor at ₹92 per kilogram. The production engineer has proposed shelling and roasting in-house instead: variable cost would be ₹84 per kilogram (raw nuts ₹61, roasting fuel and labour ₹23), and the company''s existing shelling and roasting line — currently idle for 40,000 machine-hours a year — would be used. Each kilogram requires 0.5 machine-hours. Annual demand for packed cashews is 90,000 kg. Of the ₹84, the accountant notes that ₹6 per kilogram is allocated fixed factory overhead that will be incurred whether or not the company makes the component; the remaining ₹78 is incremental. The idle line has no other use, but the commercial team warns that the outside supplier has been reliable for a decade and that in-house quality will need new inspection routines.', '[{"label": "Exhibit 1 — Cost data per kilogram", "caption": "Per kg of shelled, roasted cashews", "columns": ["Item", "₹"], "rows": [["Buy price from outside processor", "92"], ["In-house variable cost", "84"], ["— of which allocated fixed overhead (unavoidable)", "6"], ["— of which incremental cost", "78"], ["Machine-hours required per kg", "0.5"]]}, {"label": "Exhibit 2 — Capacity and demand", "caption": "Annual", "columns": ["Item", "Value"], "rows": [["Idle machine-hours available", "40,000"], ["Annual demand for packed cashews (kg)", "90,000"], ["Alternative use for the line", "None"], ["Supplier track record", "Reliable, 10 years"]]}]'::jsonb, 'Medium', 'original_phase2', TRUE, TRUE);
INSERT INTO public.cbq_cases (id, part, section, title, narrative, exhibits, difficulty, source, verified, active) VALUES ('197d6732-7c3b-510c-81bd-ca4a2395583a', 'Part 2', 'Decision Analysis', 'Kannur Textiles — a one-off export order with spare capacity', 'Kannur Textiles weaves cotton shirting. Its plant can produce 1,00,000 metres a month and is currently running at 75,000 metres, all sold domestically at ₹420 per metre. Variable production cost is ₹260 per metre; fixed manufacturing costs are ₹1,20,00,000 per month in total. An export house has offered to buy 20,000 metres a month for three months at ₹300 per metre, packed to its specification. Export packing would add ₹10 per metre, and the export house''s markets do not overlap with Kannur''s domestic customers. The sales manager is inclined to refuse, pointing out that ₹300 is below the average total cost of about ₹420 per metre.', '[{"label": "Exhibit 1 — Current operations (per month)", "caption": "Domestic only", "columns": ["Item", "Value"], "rows": [["Capacity (metres)", "1,00,000"], ["Current volume (metres)", "75,000"], ["Selling price per metre (₹)", "420"], ["Variable cost per metre (₹)", "260"], ["Total fixed costs per month (₹)", "1,20,00,000"]]}, {"label": "Exhibit 2 — Export offer", "caption": "3-month contract", "columns": ["Item", "Value"], "rows": [["Quantity per month (metres)", "20,000"], ["Price offered (₹ per metre)", "300"], ["Additional export packing (₹ per metre)", "10"], ["Market overlap with domestic sales", "None"], ["Effect on fixed costs", "None"]]}]'::jsonb, 'Medium', 'original_phase2', TRUE, TRUE);
INSERT INTO public.cbq_cases (id, part, section, title, narrative, exhibits, difficulty, source, verified, active) VALUES ('fe9cb98e-c31c-565d-8903-b004690ff7ee', 'Part 2', 'Decision Analysis', 'Kollam Marine Paints — sell at split-off or process further', 'Kollam Marine Paints runs a joint production line that produces two intermediates from one input stream: Primer-X and Enamel-Y. The joint processing cost up to the split-off point is ₹8,00,000 per month in total. At split-off, Primer-X can be sold as-is for ₹50 per litre, or processed further into Anti-Foul-X for ₹12 per litre of additional (separable) cost and sold for ₹68 per litre. Enamel-Y can be sold as-is for ₹30 per litre, or processed further into Gloss-Y for ₹14 per litre of additional cost and sold for ₹40 per litre. Monthly output is 10,000 litres of each product. The plant manager argues the joint cost must be allocated before the decision, and suggests splitting it 60/40 because ''it keeps the accounts balanced''.', '[{"label": "Exhibit 1 — Per-litre data", "caption": "Monthly output 10,000 litres of each", "columns": ["Item", "Primer-X", "Enamel-Y"], "rows": [["Sell at split-off (₹ per litre)", "50", "30"], ["Further processing cost (₹ per litre)", "12", "14"], ["Final selling price (₹ per litre)", "68", "40"], ["Incremental revenue from further processing (₹ per litre)", "18", "10"]]}, {"label": "Exhibit 2 — Joint cost", "caption": "Per month", "columns": ["Item", "Value"], "rows": [["Total joint processing cost (₹)", "8,00,000"], ["Manager''s proposed allocation", "60/40"], ["Does the allocation change any incremental flow?", "No"]]}]'::jsonb, 'Medium', 'original_phase2', TRUE, TRUE);
INSERT INTO public.cbq_cases (id, part, section, title, narrative, exhibits, difficulty, source, verified, active) VALUES ('d1e158bb-457b-541f-8b7e-07b45960d253', 'Part 2', 'Decision Analysis', 'Palakkad Granites — transfer pricing between divisions', 'Palakkad Granites has a Quarries division and a Processing division. The Quarries division cuts granite blocks at a variable cost of ₹90 per tonne and sells to outside customers at the market price of ₹150 per tonne. Annual capacity is 1,00,000 tonnes; outside demand is 70,000 tonnes. The Processing division requires 50,000 tonnes a year and can buy identical blocks from outside at ₹150, or from Quarries at a transfer price set by head office. Head office wants a price that makes each division willing to trade and that is consistent with company profit.', '[{"label": "Exhibit 1 — Current year data", "caption": "Quarries division", "columns": ["Item", "Value"], "rows": [["Variable cost per tonne (₹)", "90"], ["Market price per tonne (₹)", "150"], ["Annual capacity (tonnes)", "1,00,000"], ["Outside demand (tonnes)", "70,000"], ["Processing division''s requirement (tonnes)", "50,000"]]}, {"label": "Exhibit 2 — Possibilities", "caption": "If Quarries sells in-house", "columns": ["Scenario", "Capacity position"], "rows": [["Scenario 1 — sell 50,000 tonnes in-house", "Outside demand 70,000 + in-house 50,000 = 1,20,000 > capacity"], ["Scenario 2 — outside demand falls to 60,000", "60,000 + 50,000 = 1,10,000 > capacity"], ["Scenario 3 — outside demand falls to 40,000", "40,000 + 50,000 = 90,000 ≤ capacity"]]}]'::jsonb, 'Hard', 'original_phase2', TRUE, TRUE);
INSERT INTO public.cbq_cases (id, part, section, title, narrative, exhibits, difficulty, source, verified, active) VALUES ('509bc5ff-86a6-59b6-aec8-3ea1e485a6fc', 'Part 1', 'Technology and Analytics', 'Coimbatore Precision Parts — an ERP cutover gone wrong', 'Coimbatore Precision Parts, a 240-employee auto-components maker, replaced its ageing ERP with a new cloud system. To save time and consulting fees, the IT head chose a direct cutover on the first day of the financial year: the old system was switched off at midnight and the new one on. There had been no full-volume test with migrated data, and the opening balances were never reconciled between the two systems. Staff had watched two hours of online training. Within ten days, purchase orders were duplicating, customer balances disagreed with the subledger by ₹64,00,000, and the month-end close failed. The board asks the CFO to diagnose what went wrong and to specify the correct conversion and development approach before any restart.', '[{"label": "Exhibit 1 — What happened", "caption": "Timeline of the failed go-live", "columns": ["Item", "Detail"], "rows": [["Conversion approach", "Direct cutover at financial year-start"], ["Full-volume test with migrated data", "None performed"], ["Opening balances reconciled old vs new", "Never reconciled"], ["Staff training", "Two hours of online video"], ["Customer balance mismatch found on day 10", "₹64,00,000"]]}, {"label": "Exhibit 2 — The old system", "caption": "Before switch-off", "columns": ["Item", "Status"], "rows": [["Still functional at cutover", "Yes"], ["Data extractable for migration rehearsal", "Yes"], ["Rollback plan documented", "No"]]}]'::jsonb, 'Medium', 'original_phase2', TRUE, TRUE);
INSERT INTO public.cbq_cases (id, part, section, title, narrative, exhibits, difficulty, source, verified, active) VALUES ('ecf5fa58-096a-54b3-840f-8f757568a46c', 'Part 1', 'Technology and Analytics', 'Madurai Milk Union — ransomware, backups and data governance', 'Madurai Milk Union collects milk from 14,000 farmers twice a day. Its collection software runs on a server at the union head office, with each collection centre keying in quantities and fat readings. One evening at 17:30, a clerk opens an attachment labelled ''milk-rate-revision.pdf''; by 18:00 ransomware has encrypted the server, including the shared drive of farmer payout data. The union''s backups exist — in theory: a daily backup job has run at 02:00 every night for a year, but it has never been restored in a test, and the backup drive stays attached to the same server. The board creates a data-governance council and asks the new data manager to sort out controls, ownership and recovery capability.', '[{"label": "Exhibit 1 — Attack timeline", "caption": "The evening of the attack", "columns": ["Item", "Value"], "rows": [["Attachment opened", "17:30"], ["Encryption complete", "18:00"], ["Last successful backup before the attack", "02:00 the same day"], ["Backups restored in a test, ever", "Never"], ["Backup drive location", "Attached to the same server"]]}, {"label": "Exhibit 2 — Recovery questions", "caption": "Board''s checklist", "columns": ["Question", "Data point"], "rows": [["Data changed between last backup and attack", "15.5 hours of collection entries"], ["Recovery time objective (RTO) tolerated", "24 hours"], ["Named owner of farmer master data", "None until now"]]}]'::jsonb, 'Medium', 'original_phase2', TRUE, TRUE);
INSERT INTO public.cbq_cases (id, part, section, title, narrative, exhibits, difficulty, source, verified, active) VALUES ('e2a2d5ec-48b1-54a0-9abc-845504f1d1fc', 'Part 1', 'Technology and Analytics', 'Tiruppur Knitwear — regression forecasts and seasonal patterns', 'Tiruppur Knitwear Exports ships knitwear to overseas retailers. To plan yarn purchases, the analyst regressed monthly export orders (in thousand units) on an overseas retail confidence index: orders = 120 + 2.4 × index. The index is forecast at 50 for next quarter, and retail intelligence suggests a seasonal Diwali-quarter uplift of 12% on top of the regression estimate. The model''s R² is 0.64, fitted on 48 months of data. The commercial director wants to commit yarn volumes now and asks the analyst to defend the number, the seasonality adjustment and the model''s limits.', '[{"label": "Exhibit 1 — The model", "caption": "Fitted on 48 monthly observations", "columns": ["Item", "Value"], "rows": [["Regression equation", "Orders (’000 units) = 120 + 2.4 × retail index"], ["Forecast retail index, next quarter", "50"], ["R²", "0.64"], ["Seasonal uplift, Diwali quarter", "+12%"]]}, {"label": "Exhibit 2 — Sample history", "caption": "Recent quarters", "columns": ["Quarter", "Retail index", "Actual orders (’000)"], "rows": [["Q1", "44", "226"], ["Q2", "46", "231"], ["Q3", "48", "236"], ["Q4 (Diwali)", "48", "264"]]}]'::jsonb, 'Medium', 'original_phase2', TRUE, TRUE);
INSERT INTO public.cbq_cases (id, part, section, title, narrative, exhibits, difficulty, source, verified, active) VALUES ('26e94547-0a72-58bd-b047-ebe3ec2c4fe1', 'Part 2', 'Professional Ethics', 'Bengaluru FinTech — confidential client data and a tempting side gig', 'Arun Rao, a management accountant at Bengaluru FinTech, supports the valuations team for a client — a quick-commerce startup planning an expansion into four new cities. A college friend now works for a rival and casually asks Arun ''which cities your client is eyeing, just so I know where to avoid hiring''. The same week, a consultancy offers Arun a weekend project ''using what you know about pricing engines'' for a firm that may bid against his employer. Arun''s employment contract requires confidentiality during and after employment and contains a conflict-of-interest clause. He has taken no client files home, but he has deep knowledge of the client''s pipeline in his head.', '[{"label": "Exhibit 1 — The two requests", "caption": "This week", "columns": ["Item", "Detail"], "rows": [["Friend''s request", "Which cities the client will expand into"], ["Weekend project offer", "Consult on pricing engines for a firm that may bid against his employer"], ["Contract terms", "Confidentiality during and after employment; conflict-of-interest clause"], ["Client files taken home", "None"]]}, {"label": "Exhibit 2 — What''s in Arun''s head", "caption": "From his engagement", "columns": ["Knowledge", "Character"], "rows": [["Client''s expansion-city pipeline", "Confidential client information"], ["General valuation and modelling skills", "Transferable professional skill"], ["Employer''s proprietary pricing methodology documents", "Confidential employer information"]]}]'::jsonb, 'Medium', 'original_phase2', TRUE, TRUE);
INSERT INTO public.cbq_cases (id, part, section, title, narrative, exhibits, difficulty, source, verified, active) VALUES ('2ff72a52-c47c-5703-99d5-76b89c9d17d8', 'Part 2', 'Professional Ethics', 'Chennai Auto Components — credibility under covenant pressure', 'Meera Krishnan, CMA, is controller of Chennai Auto Components, a gear manufacturer with a ₹40-crore term loan. The loan covenant requires a minimum current ratio of 1.5 at each quarter-end. Her draft quarter-end figures show a current ratio of 1.42. The CFO asks her to ''defer the warranty accrual and stretch a few supplier payments past quarter-end'' so the ratio prints at 1.51, promising to ''fix it next quarter''. Meera''s analysis shows the underlying shortfall is real: slowing collections have genuinely eroded liquidity, and even with the adjustments the ratio would breach again next quarter. Quarterly warranty expense runs at 2.5% of sales, and quarterly sales are ₹4,000 lakh as per the exhibit.', '[{"label": "Exhibit 1 — Quarter-end data (₹ lakh)", "caption": "Draft figures", "columns": ["Item", "Value"], "rows": [["Current assets", "4,260"], ["Current liabilities", "3,000"], ["Draft current ratio", "1.42"], ["Covenant minimum", "1.5"], ["Quarterly sales", "4,000"], ["Warranty expense rate", "2.5% of sales"]]}, {"label": "Exhibit 2 — The CFO''s proposal", "caption": "Unaudited adjustments", "columns": ["Item", "Effect"], "rows": [["Defer warranty accrual", "Understates current liabilities by ₹100 lakh"], ["Stretch supplier payments past quarter-end", "Understates current liabilities by ₹50 lakh"], ["Underlying collections problem", "Unresolved — ratio would breach again next quarter"]]}]'::jsonb, 'Medium', 'original_phase2', TRUE, TRUE);
INSERT INTO public.cbq_cases (id, part, section, title, narrative, exhibits, difficulty, source, verified, active) VALUES ('6171678a-7ba0-5d0e-9891-482dcfb20fa3', 'Part 2', 'Professional Ethics', 'Hyderabad Pharma — an overseas agent''s ''consulting fee''', 'Hyderabad Pharma, a generics exporter, is bidding for a three-year hospital-supply contract in a new overseas market worth ₹20 crore. A local agent offers to ''facilitate regulatory approvals'' for a 15% ''consulting fee'' — three times the market rate of ~5% — payable to an offshore account. The agent will not sign a compliance certification, will not describe deliverables, and hints that part of the fee ''greases officials, as is normal here''. The commercial head argues the deal is too important to lose and that ''in that market, everyone does it''. The contract margin at standard 5% commission would be ₹2.6 crore; winning matters to the division''s bonus pool.', '[{"label": "Exhibit 1 — The agent''s terms", "caption": "As proposed", "columns": ["Item", "Detail"], "rows": [["Contract value", "₹20 crore"], ["Agent''s requested fee", "15% to an offshore account"], ["Market-rate commission", "≈5%"], ["Compliance certification", "Refused"], ["Deliverables described", "None"], ["Hint about officials", "Explicit"]]}, {"label": "Exhibit 2 — Commercial stakes", "caption": "Divisional view", "columns": ["Item", "Value"], "rows": [["Contract margin at standard commission", "₹2.6 crore"], ["Division bonus pool", "Materially affected by winning"], ["Local practice claim", "''Everyone does it''"]]}]'::jsonb, 'Hard', 'original_phase2', TRUE, TRUE);
INSERT INTO public.cbq_cases (id, part, section, title, narrative, exhibits, difficulty, source, verified, active) VALUES ('92352e87-b0b0-55f4-8901-69257efacdac', 'Part 1', 'Internal Controls', 'Kochi Port Logistics — mapping findings to the COSO framework', 'Kochi Port Logistics handles container yard operations and customs documentation for exporters. Internal audit has just completed a review of the revenue and cash cycle and tabled five findings: (1) warehouse cashiers are hired without reference checks and treasury turnover is 60% a year; (2) nobody assessed the fraud or error risk of the new online-payments channel before it went live; (3) customer credit limits exist on paper but the order-entry system does not enforce them; (4) month-end exception reports on billing errors reach management three weeks late; (5) last year''s audit findings were never followed up and remain open. The audit committee asks the controller to place each finding in the COSO Internal Control — Integrated Framework component it belongs to, and to report on transaction-testing results: 60 revenue transactions were sampled and 3 deviated from the credit-approval control, against a tolerable deviation rate of 4%.', '[{"label": "Exhibit 1 — The five findings", "caption": "Internal audit report", "columns": ["#", "Finding"], "rows": [["1", "Cashiers hired without reference checks; treasury turnover 60% a year"], ["2", "New online-payments channel launched with no fraud-risk assessment"], ["3", "Credit limits documented but not enforced by the order system"], ["4", "Exception reports reach management three weeks late"], ["5", "Prior-year audit findings never followed up"]]}, {"label": "Exhibit 2 — Attribute testing of credit approvals", "caption": "60 transactions sampled", "columns": ["Item", "Value"], "rows": [["Sample size", "60"], ["Deviations found", "3"], ["Sample deviation rate", "5.0%"], ["Tolerable deviation rate", "4%"], ["Conclusion", "Rate exceeds tolerable — reliance not supported"]]}]'::jsonb, 'Medium', 'original_phase2', TRUE, TRUE);
INSERT INTO public.cbq_cases (id, part, section, title, narrative, exhibits, difficulty, source, verified, active) VALUES ('51affae8-d0ab-5301-ac9c-95cffe4a8062', 'Part 1', 'Internal Controls', 'Salem Steel Traders — IT general controls in a distributor', 'Salem Steel Traders runs its entire business on an ERP: quotations, orders, inventory, dispatch and ledgers. A new IT auditor reviews the general controls. She finds: 12 of the 480 user accounts have been dormant for over a year but remain active; one developer can write code, approve his own change ticket and deploy to production; password policy is eight characters with no lockout; backups run nightly but are never restored in tests; and branch offices connect over the public internet with no encryption. Application-level edit checks inside the ERP work well — negative quantities and duplicate vendor masters are rejected automatically — but the auditor reminds management that application controls can only be as reliable as the general controls underneath them.', '[{"label": "Exhibit 1 — ITGC findings", "caption": "Audit summary", "columns": ["#", "Finding"], "rows": [["1", "12 of 480 accounts dormant over a year but still active"], ["2", "Developer can code, self-approve and deploy to production"], ["3", "8-character passwords, no lockout"], ["4", "Backups never test-restored"], ["5", "Branch traffic unencrypted over public internet"]]}, {"label": "Exhibit 2 — Application controls (working)", "caption": "ERP edit checks", "columns": ["Control", "Status"], "rows": [["Reject negative invoice quantities", "Working"], ["Block duplicate vendor masters", "Working"], ["Enforce credit limit at order entry", "Working"]]}]'::jsonb, 'Medium', 'original_phase2', TRUE, TRUE);
INSERT INTO public.cbq_cases (id, part, section, title, narrative, exhibits, difficulty, source, verified, active) VALUES ('f067643e-6caf-5f81-b448-8d4f3990884c', 'Part 2', 'Financial Statement Analysis', 'Mangalore Chemical Works — reading the ratio profile of a mid-size manufacturer', 'Mangalore Chemical Works makes industrial solvents. The analyst at its lender has the latest annual figures: sales ₹72,00,000; cost of goods sold ₹43,20,000; EBIT ₹9,00,000; interest expense ₹3,00,000; net income ₹4,50,000; equity ₹30,00,000; current assets ₹9,60,000 (of which inventory ₹3,60,000 and receivables ₹5,40,000); current liabilities ₹6,00,000; average inventory for the year ₹7,20,000. The lender''s benchmark file shows comparable solvent makers running inventory turnover near 9× and interest cover near 5×. The credit file is up for renewal, and the analyst must write a two-paragraph view on profitability, liquidity and the quality of both.', '[{"label": "Exhibit 1 — Annual income data", "caption": "₹ unless stated", "columns": ["Item", "Value"], "rows": [["Sales", "72,00,000"], ["Cost of goods sold", "43,20,000"], ["EBIT", "9,00,000"], ["Interest expense", "3,00,000"], ["Net income", "4,50,000"], ["Equity", "30,00,000"]]}, {"label": "Exhibit 2 — Position and operating data", "caption": "Year-end", "columns": ["Item", "Value"], "rows": [["Current assets", "9,60,000"], ["— Inventory", "3,60,000"], ["— Receivables", "5,40,000"], ["Current liabilities", "6,00,000"], ["Average inventory", "7,20,000"], ["Industry benchmarks", "Inventory turnover ≈ 9×; interest cover ≈ 5×"]]}]'::jsonb, 'Medium', 'original_phase2', TRUE, TRUE);
INSERT INTO public.cbq_cases (id, part, section, title, narrative, exhibits, difficulty, source, verified, active) VALUES ('9f460f95-e06c-5181-946c-93c247bc6e45', 'Part 2', 'Financial Statement Analysis', 'Kochi Retail Group — judging the quality of reported earnings', 'Kochi Retail Group owns nine apparel stores. The year just closed with sales ₹30,00,000 and SG&A ₹9,00,000. An analyst reviewing the annual report notices three things. First, this year management changed its software accounting: ₹24,00,000 of new point-of-sale and inventory software, previously treated as an expense, was capitalised and is being amortised over four years (₹6,00,000 a year) — management says this better reflects the assets'' useful lives. Second, December sales spiked 40% above trend, with several large sales to a single wholesale customer recorded on the last day of the year on ''bill-and-hold'' terms — goods stay in Kochi''s warehouse until the customer calls for them. Third, the cash conversion cycle has lengthened: receivable days have drifted from 35 to 45, inventory days sit at 60, and payable days compressed to 30 as suppliers tightened terms.', '[{"label": "Exhibit 1 — P&L excerpts", "caption": "Year just closed", "columns": ["Item", "Value"], "rows": [["Sales", "30,00,000"], ["SG&A", "9,00,000"], ["Software capitalised this year (old policy: expense)", "24,00,000"], ["New amortisation charge", "6,00,000 per year"]]}, {"label": "Exhibit 2 — Working-capital cycle", "caption": "Days", "columns": ["Item", "Value"], "rows": [["Receivable days (DSO)", "45"], ["Inventory days (DIO)", "60"], ["Payable days (DPO)", "30"], ["December spike", "Sales +40% vs trend, bill-and-hold to one wholesaler"]]}]'::jsonb, 'Hard', 'original_phase2', TRUE, TRUE);
INSERT INTO public.cbq_cases (id, part, section, title, narrative, exhibits, difficulty, source, verified, active) VALUES ('b233b7f8-c03a-525b-86f7-f696399a3ca5', 'Part 2', 'Investment Decisions', 'Kozhikode Wind Energy — appraising a rooftop solar programme', 'Kozhikode Wind Energy''s facility team proposes installing rooftop solar across its two plants. The package costs ₹50,00,000 fully installed. It will save ₹14,00,000 a year in electricity for five years, after which the panels are assumed worthless. The finance director requires a 12% return and gives the team the 5-year annuity present-value factor at 12%: 3.6048. A ₹3,00,000 feasibility study was completed last month. The facilities head favours the project because ''it pays for itself in under four years''; the CFO wants the full appraisal before committing.', '[{"label": "Exhibit 1 — Project data", "caption": "5-year horizon", "columns": ["Item", "Value"], "rows": [["Initial cost (₹)", "50,00,000"], ["Annual electricity savings (₹)", "14,00,000"], ["Life", "5 years"], ["Salvage value", "Nil"], ["Required return", "12%"], ["PV annuity factor, 5 yrs @ 12%", "3.6048"], ["Feasibility study already paid (₹)", "3,00,000"]]}, {"label": "Exhibit 2 — Views on the table", "caption": "Who says what", "columns": ["Person", "Position"], "rows": [["Facilities head", "''Pays for itself in under four years''"], ["CFO", "Full NPV appraisal first"]]}]'::jsonb, 'Medium', 'original_phase2', TRUE, TRUE);
INSERT INTO public.cbq_cases (id, part, section, title, narrative, exhibits, difficulty, source, verified, active) VALUES ('97bd72f4-3a6c-5303-a23b-de8020e0d2d8', 'Part 2', 'Investment Decisions', 'Trivandrum Logistics Park — replacing a forklift fleet after tax', 'Trivandrum Logistics Park is evaluating a new fleet of electric forklifts to replace its diesel units. The electric fleet costs ₹12,00,000 installed, will cut operating costs by ₹4,20,000 a year pre-tax for five years, and has an expected salvage value of ₹1,00,000 at the end of year 5. It will be depreciated straight-line to that salvage over five years. The tax rate is 25%; the required return is 10%; the PV annuity factor for 5 years at 10% is 3.7908 and the single-sum factor for year 5 is 0.6209. The old diesel forklifts are fully depreciated with zero salvage value — their original cost was ₹8,00,000.', '[{"label": "Exhibit 1 — New fleet data", "caption": "5-year life", "columns": ["Item", "Value"], "rows": [["Installed cost (₹)", "12,00,000"], ["Pre-tax annual savings (₹)", "4,20,000"], ["Salvage value, end of year 5 (₹)", "1,00,000"], ["Depreciation basis", "Straight-line to salvage over 5 years"], ["Tax rate", "25%"], ["Required return", "10%"]]}, {"label": "Exhibit 2 — Discount factors @10%", "caption": "Given", "columns": ["Factor", "Value"], "rows": [["5-year annuity", "3.7908"], ["Year-5 single sum", "0.6209"]]}, {"label": "Exhibit 3 — Old fleet", "caption": "Status", "columns": ["Item", "Value"], "rows": [["Original cost (₹)", "8,00,000"], ["Book value", "Fully depreciated, zero"], ["Salvage value", "Nil"]]}]'::jsonb, 'Hard', 'original_phase2', TRUE, TRUE);
INSERT INTO public.cbq_cases (id, part, section, title, narrative, exhibits, difficulty, source, verified, active) VALUES ('79e48838-d66b-51a6-91af-bb128ec4f709', 'Part 1', 'Planning, Budgeting and Forecasting', 'Ernakulam Bakery Chain — flexible budget performance for festive season', 'Ernakulam Bakery Chain budgeted the Onam season at 50,000 boxes of assorted bakes at ₹40 per box, variable cost ₹24 per box, and fixed costs ₹5,00,000 for the quarter. Demand ran hot: 55,000 boxes were sold. Revenue came in at ₹22,00,000, variable costs at ₹14,30,000 and fixed costs at ₹5,10,000. The managing partner is pleased — ''we beat the budget'' — but the accountant points out the static comparison mixes a volume effect with a cost effect, and prepares a flexible budget at the actual volume to separate the two.', '[{"label": "Exhibit 1 — Static budget vs actuals", "caption": "Onam quarter", "columns": ["Item", "Static budget", "Actual"], "rows": [["Boxes sold", "50,000", "55,000"], ["Revenue (₹)", "20,00,000", "22,00,000"], ["Variable costs (₹)", "12,00,000", "14,30,000"], ["Fixed costs (₹)", "5,00,000", "5,10,000"], ["Operating income (₹)", "3,00,000", "2,60,000"]]}, {"label": "Exhibit 2 — Standards", "caption": "Per box", "columns": ["Item", "Value"], "rows": [["Price", "₹40"], ["Variable cost", "₹24"], ["Contribution", "₹16"]]}]'::jsonb, 'Medium', 'original_phase2', TRUE, TRUE);
INSERT INTO public.cbq_cases (id, part, section, title, narrative, exhibits, difficulty, source, verified, active) VALUES ('7f4836b9-ed81-5bd3-bc42-47e7ac06a7b1', 'Part 1', 'Planning, Budgeting and Forecasting', 'Thrissur Hospitals Group — building a cash budget around slow collections', 'Thrissur Hospitals Group runs a diagnostic centre whose patient collections follow a strict rhythm: 60% of a month''s billings are collected in the same month, 40% in the following month. November billings were ₹10,00,000 and December billings are forecast at ₹12,00,000. Cash on 1 December is ₹80,000. December disbursements — salaries, reagents, rent and equipment instalments — total ₹10,50,000. The group keeps a minimum cash balance of ₹1,00,000 and borrows from its bank in multiples of ₹50,000 at 1% per month interest when the budget shows a shortfall.', '[{"label": "Exhibit 1 — Collection pattern", "caption": "Patient billings", "columns": ["Item", "Value"], "rows": [["Collected in month of billing", "60%"], ["Collected in following month", "40%"], ["November billings (₹)", "10,00,000"], ["December billings, forecast (₹)", "12,00,000"]]}, {"label": "Exhibit 2 — December cash plan", "caption": "₹", "columns": ["Item", "Value"], "rows": [["Cash on 1 December", "80,000"], ["December disbursements", "10,50,000"], ["Minimum cash balance", "1,00,000"], ["Credit line", "Multiples of ₹50,000, 1% per month"]]}]'::jsonb, 'Medium', 'original_phase2', TRUE, TRUE);
INSERT INTO public.cbq_cases (id, part, section, title, narrative, exhibits, difficulty, source, verified, active) VALUES ('840eeb83-ef9a-5a6d-b8e2-063ef9dd0445', 'Part 1', 'Performance Management', 'Kannur Resorts — ROI versus residual income, and a balanced scorecard', 'Kannur Resorts owns two divisions. Division X (backwater resorts) reports income ₹18,00,000 on assets of ₹90,00,000; Division Y (hill resorts) reports income ₹12,00,000 on assets of ₹50,00,000. Corporate policy sets a minimum return of 12% on divisional assets. A new opportunity has surfaced: a ₹10,00,000 eco-camp project expected to earn ₹1,60,000 a year. Division X''s manager is lukewarm — the project would ''drag my ROI down''. The CFO wonders whether the measurement method, not the project, is the problem, and whether the bonus plan should also track non-financial performance.', '[{"label": "Exhibit 1 — Divisional results", "caption": "Latest year", "columns": ["Item", "Division X", "Division Y"], "rows": [["Income (₹)", "18,00,000", "12,00,000"], ["Assets (₹)", "90,00,000", "50,00,000"], ["Minimum required return", "12%", "12%"]]}, {"label": "Exhibit 2 — New project", "caption": "Eco-camp", "columns": ["Item", "Value"], "rows": [["Investment (₹)", "10,00,000"], ["Expected annual income (₹)", "1,60,000"], ["Project return", "16%"]]}]'::jsonb, 'Medium', 'original_phase2', TRUE, TRUE);
INSERT INTO public.cbq_cases (id, part, section, title, narrative, exhibits, difficulty, source, verified, active) VALUES ('dfe6a6ec-c247-5ec4-bb49-bcb6688c8e0c', 'Part 2', 'Corporate Finance', 'Kochi Marine Engineering — the cost of capital behind a new dock contract', 'Kochi Marine Engineering builds and repairs workboats. It is bidding for a five-year maintenance contract that requires ₹40,00,000 of specialised equipment. The finance team estimates the contract''s expected return at 11.5%. The company''s capital structure is 40% debt, 60% equity by market value. Its pre-tax cost of debt is 9%, its cost of equity is estimated at 13%, and the corporate tax rate is 25%. The CFO refuses to approve any project below the company''s cost of capital and asks the analyst to build the hurdle from first principles.', '[{"label": "Exhibit 1 — Capital structure and costs", "caption": "Market values", "columns": ["Item", "Value"], "rows": [["Debt weight", "40%"], ["Equity weight", "60%"], ["Pre-tax cost of debt", "9%"], ["Cost of equity", "13%"], ["Tax rate", "25%"]]}, {"label": "Exhibit 2 — The contract", "caption": "Under review", "columns": ["Item", "Value"], "rows": [["Equipment outlay (₹)", "40,00,000"], ["Expected return", "11.5%"], ["CFO''s rule", "Approve only above the cost of capital"]]}]'::jsonb, 'Medium', 'original_phase2', TRUE, TRUE);
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('f55bae99-9406-50ae-afd8-12781c0ce311', 1, 'mcq', 13, 'In the make-or-buy analysis, which cost per kilogram is <b>relevant</b> to the decision?', NULL, '{"options": ["₹92 buy price", "₹84 full in-house variable cost as recorded", "₹78 incremental in-house cost", "₹6 allocated fixed overhead"]}'::jsonb, '{"value": "C"}'::jsonb, 'Only incremental costs differ between alternatives. The ₹6 of allocated fixed overhead is unavoidable, and the ₹92 buy price is relevant only as the comparator for the units actually bought.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('f55bae99-9406-50ae-afd8-12781c0ce311', 2, 'num', 13, 'Given the idle capacity, calculate the maximum quantity the company can make in-house, <b>in kilograms</b>.', NULL, '{}'::jsonb, '{"value": 80000}'::jsonb, '40,000 idle machine-hours ÷ 0.5 hours per kg = 80,000 kg. Demand is 90,000 kg, so 10,000 kg must still be bought if the company makes.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('f55bae99-9406-50ae-afd8-12781c0ce311', 3, 'num', 13, 'Calculate the <b>relevant saving per kilogram</b> on each kilogram made in-house rather than bought.', NULL, '{}'::jsonb, '{"value": 14}'::jsonb, 'Relevant make cost ₹78 vs buy price ₹92 → saving of ₹14 per kg on units made. The unavoidable ₹6 fixed overhead is excluded from both sides.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('f55bae99-9406-50ae-afd8-12781c0ce311', 4, 'multi', 14, 'Which <b>two</b> of the following are legitimate qualitative factors in this decision?', NULL, '{"options": ["The supplier''s ten-year reliability record", "The ₹2,00,000 feasibility study the company paid for last year", "Quality-control arrangements the company must add for in-house roasting", "The allocated fixed overhead rate chosen by the accountant", "Depreciation already recorded on the idle line"]}'::jsonb, '{"values": [0, 2]}'::jsonb, 'Supplier reliability and the new inspection routines are genuine non-cost factors. The feasibility study is sunk, and the overhead rate and past depreciation do not change with the decision.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('f55bae99-9406-50ae-afd8-12781c0ce311', 5, 'dnd', 16, 'Classify each item as <b>relevant</b> or <b>irrelevant</b> to the make-or-buy decision.', NULL, '{"items": [{"id": "a", "text": "The ₹14 per kg saving on units the line can produce"}, {"id": "b", "text": "The ₹6 per kg unavoidable allocated fixed overhead"}, {"id": "c", "text": "The ₹2,00,000 feasibility study already paid for"}, {"id": "d", "text": "The 0.5 machine-hours consumed per kilogram made"}], "zones": {"rel": "Relevant", "irr": "Irrelevant"}}'::jsonb, '{"placement": {"a": "rel", "b": "irr", "c": "irr", "d": "rel"}}'::jsonb, 'The per-unit saving and the scarce machine-hours change with the decision, so they are relevant. Unavoidable overhead and sunk study costs are identical under both alternatives.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('f55bae99-9406-50ae-afd8-12781c0ce311', 6, 'mcq', 13, 'If the line''s idle hours could instead be <b>rented out</b> for ₹6,00,000 a year, how would that change the analysis?', NULL, '{"options": ["It is ignored — rental income is a financing matter", "It is an opportunity cost of making, raising the effective cost of in-house production", "It is added to the saving from buying", "It is a sunk cost"]}'::jsonb, '{"value": "B"}'::jsonb, 'Foregone rental income is an opportunity cost of using the hours to make. It must be covered by the total ₹14 saving (80,000 kg × ₹14 = ₹11,20,000) before making is worthwhile.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('f55bae99-9406-50ae-afd8-12781c0ce311', 7, 'mcq', 15, 'Which statement about the <b>10,000 kg the company cannot make itself</b> is correct?', NULL, '{"options": ["They should be made anyway by working overtime at any cost", "They should still be bought at ₹92, because the make-or-buy saving applies only to units the constrained line can produce", "They should be bought only if the buy price falls below ₹78", "They should not be purchased at all"]}'::jsonb, '{"value": "B"}'::jsonb, 'With no capacity to make them, the comparison for those units is simply: buy at ₹92 or don''t have them — the ₹14 saving was never available on them. Capacity, not demand, bounds the make quantity.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('197d6732-7c3b-510c-81bd-ca4a2395583a', 1, 'num', 13, 'Calculate the <b>incremental contribution per metre</b> from the export order.', NULL, '{}'::jsonb, '{"value": 30}'::jsonb, '₹300 − ₹260 variable production − ₹10 export packing = ₹30 per metre. The fixed costs are unchanged, so only these flows matter.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('197d6732-7c3b-510c-81bd-ca4a2395583a', 2, 'mcq', 13, 'Why is the sales manager''s <b>₹420 average-cost argument</b> wrong?', NULL, '{"options": ["Because average cost includes fixed costs that do not change if the order is accepted", "Because export orders never carry variable costs", "Because ₹300 is actually above average cost", "Because fixed costs should be doubled for export"]}'::jsonb, '{"value": "A"}'::jsonb, 'At spare capacity, fixed cost per unit is an allocation, not an incremental cost. The order adds ₹30 per metre of contribution and nothing to fixed costs.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('197d6732-7c3b-510c-81bd-ca4a2395583a', 3, 'num', 14, 'Calculate the effect of accepting the order on <b>monthly operating income</b> (enter the amount in ₹).', NULL, '{}'::jsonb, '{"value": 600000}'::jsonb, '20,000 metres × ₹30 = ₹6,00,000 additional monthly operating income, for each of the three months.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('197d6732-7c3b-510c-81bd-ca4a2395583a', 4, 'multi', 14, 'Which <b>two</b> conditions must hold for this order to be acceptable as analysed?', NULL, '{"options": ["There is genuinely idle capacity", "The export volumes do not displace domestic sales at ₹420", "The export house will pay within seven days", "The order improves the company''s image", "The unit price covers full absorption cost"]}'::jsonb, '{"values": [0, 1]}'::jsonb, 'Acceptance logic requires spare capacity and no cannibalisation of the ₹420 domestic contribution. Payment terms, image and absorption-cost coverage are irrelevant to the incremental case.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('197d6732-7c3b-510c-81bd-ca4a2395583a', 5, 'dnd', 16, 'Classify each item as <b>relevant</b> or <b>irrelevant</b> to accepting the export order.', NULL, '{"items": [{"id": "a", "text": "The ₹30 per metre incremental contribution"}, {"id": "b", "text": "The ₹1,20,00,000 monthly fixed costs"}, {"id": "c", "text": "The ₹10 per metre export packing cost"}, {"id": "d", "text": "The ₹420 domestic price"}], "zones": {"rel": "Relevant", "irr": "Irrelevant"}}'::jsonb, '{"placement": {"a": "rel", "b": "irr", "c": "rel", "d": "irr"}}'::jsonb, 'Contribution and packing change with the decision. Fixed costs do not change at idle capacity, and the domestic price only matters if the order would displace domestic volume — Exhibit 2 says it does not.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('197d6732-7c3b-510c-81bd-ca4a2395583a', 6, 'num', 13, 'Suppose domestic volume were 90,000 metres instead of 75,000. How many metres of the order could the plant accept <b>without giving up domestic sales</b>?', NULL, '{}'::jsonb, '{"value": 10000}'::jsonb, '1,00,000 capacity − 90,000 domestic = 10,000 spare metres. The rest of the order would displace ₹160 of domestic contribution (₹420 − ₹260), which the ₹30 export contribution cannot justify.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('197d6732-7c3b-510c-81bd-ca4a2395583a', 7, 'mcq', 15, 'Which <b>additional factor</b> could still make the order unattractive even with spare capacity?', NULL, '{"options": ["The export house reselling into Kannur''s domestic market at low prices", "A slight increase in electricity cost included in the ₹260", "The order lasting only three months", "The export house paying in a foreign currency that converts to rupees"]}'::jsonb, '{"value": "A"}'::jsonb, 'Price erosion in the home market is the classic hidden cost of one-off low-price orders. The other items are either already in the numbers or immaterial.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('fe9cb98e-c31c-565d-8903-b004690ff7ee', 1, 'mcq', 13, 'In a sell-or-process-further decision, the joint cost up to split-off is:', NULL, '{"options": ["Allocated on a sales-value basis before deciding", "Relevant because it is large", "Irrelevant — it is incurred under either alternative", "Deducted from the further-processing cost"]}'::jsonb, '{"value": "C"}'::jsonb, 'Joint costs are sunk at split-off: they have been incurred whatever the company does next. Only incremental revenue and separable further cost matter.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('fe9cb98e-c31c-565d-8903-b004690ff7ee', 2, 'num', 13, 'Calculate the <b>incremental profit per litre</b> from processing Primer-X further into Anti-Foul-X.', NULL, '{}'::jsonb, '{"value": 6}'::jsonb, 'Incremental revenue ₹68 − ₹50 = ₹18; less separable cost ₹12 → ₹6 per litre. Positive, so process further.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('fe9cb98e-c31c-565d-8903-b004690ff7ee', 3, 'mcq', 13, 'What is the correct decision for <b>Enamel-Y</b>?', NULL, '{"options": ["Process further — final price is higher", "Sell at split-off — incremental revenue ₹10 is less than the ₹14 further cost", "Process further if joint cost is allocated 40%", "Either — the result is the same"]}'::jsonb, '{"value": "B"}'::jsonb, '₹40 − ₹30 = ₹10 of incremental revenue against ₹14 of separable cost: a ₹4 per litre loss from processing further. Sell at split-off.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('fe9cb98e-c31c-565d-8903-b004690ff7ee', 4, 'dnd', 16, 'Classify each figure as <b>relevant</b> or <b>irrelevant</b> to the decision.', NULL, '{"items": [{"id": "a", "text": "The ₹8,00,000 joint cost"}, {"id": "b", "text": "The ₹12 per litre separable cost of Anti-Foul-X"}, {"id": "c", "text": "The ₹50 split-off price of Primer-X"}, {"id": "d", "text": "The ₹68 final price of Anti-Foul-X"}], "zones": {"rel": "Relevant", "irr": "Irrelevant"}}'::jsonb, '{"placement": {"a": "irr", "b": "rel", "c": "rel", "d": "rel"}}'::jsonb, 'Everything after split-off — separable costs, split-off values, final prices — is incremental. The joint cost is common to all alternatives.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('fe9cb98e-c31c-565d-8903-b004690ff7ee', 5, 'num', 14, 'Calculate the <b>total additional monthly income</b> from the optimal plan (₹).', NULL, '{}'::jsonb, '{"value": 60000}'::jsonb, 'Process all 10,000 litres of Primer-X: 10,000 × ₹6 = ₹60,000. Sell all Enamel-Y at split-off: ₹0 incremental. Optimal plan adds ₹60,000 per month.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('fe9cb98e-c31c-565d-8903-b004690ff7ee', 6, 'multi', 14, 'Which <b>two</b> changes could reverse the decision on Primer-X?', NULL, '{"options": ["Anti-Foul-X''s market price rises", "The separable cost falls below ₹18 per litre", "The joint cost allocation changes to 50/50", "Output rises from 10,000 to 12,000 litres with unchanged unit economics", "The split-off price of Primer-X rises to ₹60"]}'::jsonb, '{"values": [1, 4]}'::jsonb, 'Processing is worthwhile only while incremental revenue exceeds ₹12 of separable cost; a higher split-off price (₹60) cuts incremental revenue to ₹8, killing the case. Allocation shuffles and volume changes with unchanged unit economics do not change the per-litre logic.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('fe9cb98e-c31c-565d-8903-b004690ff7ee', 7, 'mcq', 15, 'The manager''s ''keep the accounts balanced'' allocation concern is best answered by:', NULL, '{"options": ["Refusing to allocate — inventory costing rules no longer apply", "Allocating for inventory/financial reporting purposes, but deciding on incremental flows — the two uses are separate", "Allocating 60/40 because the manager suggested it", "Stopping joint production"]}'::jsonb, '{"value": "B"}'::jsonb, 'Joint-cost allocation is required for inventory costing, but decisions must ignore sunk joint costs. The same number can be allocated one way for the ledger and ignored for the decision — no contradiction.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('d1e158bb-457b-541f-8b7e-07b45960d253', 1, 'mcq', 13, 'In <b>Scenario 1</b>, the minimum transfer price the Quarries division should accept is:', NULL, '{"options": ["₹90", "₹120", "₹150", "₹100"]}'::jsonb, '{"value": "C"}'::jsonb, 'At full capacity every tonne transferred loses a ₹150 outside sale. The minimum price is the market price of ₹150; anything less makes Quarries worse off than selling outside.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('d1e158bb-457b-541f-8b7e-07b45960d253', 2, 'num', 14, 'In <b>Scenario 3</b>, where spare capacity exists, calculate the minimum transfer price (₹ per tonne).', NULL, '{}'::jsonb, '{"value": 90}'::jsonb, 'With 10,000 tonnes of idle capacity, the incremental cost of an internal tonne is just the variable cost of ₹90. The division should accept any price at or above ₹90.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('d1e158bb-457b-541f-8b7e-07b45960d253', 3, 'mcq', 13, 'The <b>maximum</b> price the Processing division should ever agree to pay is:', NULL, '{"options": ["The ₹150 outside market price", "The ₹90 variable cost", "The company average cost", "Whatever head office suggests"]}'::jsonb, '{"value": "A"}'::jsonb, 'No division should pay more internally than it would pay an outside supplier for an identical block — ₹150 is the ceiling.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('d1e158bb-457b-541f-8b7e-07b45960d253', 4, 'dnd', 16, 'Match each scenario to the pricing rule it implies.', NULL, '{"items": [{"id": "a", "text": "Scenario 1 — full capacity, outside demand waiting"}, {"id": "b", "text": "Scenario 3 — idle capacity, no outside demand lost"}, {"id": "c", "text": "Scenario 2 — capacity short by 10,000 tonnes"}, {"id": "d", "text": "Processing buys outside at ₹150 while Quarries has idle capacity"}], "zones": {"mkt": "Price at market", "var": "Price at variable cost", "part": "Hybrid / dual price", "bad": "Dysfunctional outcome"}}'::jsonb, '{"placement": {"a": "mkt", "b": "var", "c": "part", "d": "bad"}}'::jsonb, 'Full capacity forces market pricing. Idle capacity allows variable-cost pricing. A partial shortfall supports a negotiated or dual price. Buying outside while an internal unit sits idle destroys company contribution — the classic dysfunctional transfer-pricing outcome.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('d1e158bb-457b-541f-8b7e-07b45960d253', 5, 'num', 13, 'In Scenario 1, calculate the <b>company contribution per tonne</b> when a tonne is transferred internally instead of sold outside (₹).', NULL, '{}'::jsonb, '{"value": 0}'::jsonb, 'Outside sale: ₹150 − ₹90 = ₹60 contribution. Internal transfer at market-based decision-making also yields ₹150 − ₹90 = ₹60. The company is indifferent per tonne — which is exactly why ₹150 is the right floor.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('d1e158bb-457b-541f-8b7e-07b45960d253', 6, 'multi', 14, 'Which <b>two</b> are recognised transfer-pricing bases?', NULL, '{"options": ["Market-based", "Cost-plus", "Whatever maximises the selling division''s bonus", "The price set last decade", "A price the buying division unilaterally dictates"]}'::jsonb, '{"values": [0, 1]}'::jsonb, 'Market-based and cost-based (cost-plus) prices are the standard bases, often refined by negotiation. Prices set to game divisional bonuses or dictated unilaterally sacrifice goal congruence.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('d1e158bb-457b-541f-8b7e-07b45960d253', 7, 'mcq', 15, 'If divisions are evaluated on <b>divisional profit</b>, a variable-cost transfer price with idle capacity can cause:', NULL, '{"options": ["The buying division to refuse units that would benefit the company", "The selling division to show a loss on internal sales, discouraging it from supplying", "Automatic optimal decisions", "The outside market price to fall"]}'::jsonb, '{"value": "B"}'::jsonb, 'At a ₹90 variable-cost transfer, Quarries earns zero margin on internal tonnes and may prefer not to supply even when the company gains. This is why negotiated or dual pricing exists — the transfer price changes behaviour, not company economics.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('509bc5ff-86a6-59b6-aec8-3ea1e485a6fc', 1, 'mcq', 13, 'Which conversion approach would most likely have <b>exposed the migration errors before they hurt operations</b>?', NULL, '{"options": ["Direct cutover, but on a quieter month", "Parallel running of old and new systems with reconciled outputs", "Direct cutover with more training", "Phased conversion of the chart of accounts only"]}'::jsonb, '{"value": "B"}'::jsonb, 'Running both systems in parallel lets the company compare outputs — exactly how a ₹64,00,000 subledger mismatch would have been caught during a controlled period instead of in live operations.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('509bc5ff-86a6-59b6-aec8-3ea1e485a6fc', 2, 'dnd', 16, 'Place the SDLC stages in the <b>correct order</b> for the restart project.', NULL, '{"items": [{"id": "a", "text": "Physical design — databases, interfaces, configuration"}, {"id": "b", "text": "Systems analysis — requirements and feasibility"}, {"id": "c", "text": "Operations and maintenance"}, {"id": "d", "text": "Implementation and conversion"}, {"id": "e", "text": "Conceptual design — what the system will do"}], "zones": {"s1": "Step 1", "s2": "Step 2", "s3": "Step 3", "s4": "Step 4", "s5": "Step 5"}}'::jsonb, '{"placement": {"b": "s1", "e": "s2", "a": "s3", "d": "s4", "c": "s5"}}'::jsonb, 'The life cycle moves from understanding (analysis) through what the system will do (conceptual design) and how (physical design), to conversion, then ongoing operations and maintenance.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('509bc5ff-86a6-59b6-aec8-3ea1e485a6fc', 3, 'multi', 14, 'Which <b>two</b> pre-go-live controls were skipped and directly caused the failure?', NULL, '{"options": ["Full-volume testing with migrated data", "Reconciliation of opening balances between old and new systems", "Buying faster network switches", "More project-branded merchandise", "Shorter project status meetings"]}'::jsonb, '{"values": [0, 1]}'::jsonb, 'Volume-tested data migration and balance reconciliation are the two controls whose absence made the failure certain. The other options are irrelevant to the defect.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('509bc5ff-86a6-59b6-aec8-3ea1e485a6fc', 4, 'list', 14, 'Match each <b>conversion approach</b> to its risk-and-cost profile.', NULL, '{"fields": [{"label": "Parallel running is", "options": ["Cheapest and riskiest", "Most expensive but safest", "Middle on both", "Used for one site only"]}, {"label": "Direct cutover is", "options": ["Cheapest and riskiest", "Most expensive but safest", "Middle on both", "Used for one site only"]}]}'::jsonb, '{"values": ["Most expensive but safest", "Cheapest and riskiest"]}'::jsonb, 'Parallel conversion duplicates work for a period, so it costs most but catches errors. Direct cutover simply swaps systems at a point in time — least cost, no fallback, highest risk.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('509bc5ff-86a6-59b6-aec8-3ea1e485a6fc', 5, 'mcq', 13, 'The purpose of a <b>post-implementation review</b> is to:', NULL, '{"options": ["Assign blame for the failed close", "Compare results against the original objectives and capture lessons for future projects", "Extend the project budget", "Cancel the maintenance contract"]}'::jsonb, '{"value": "B"}'::jsonb, 'A PIR is a structured look back: did the system meet requirements, what did the project teach us, what must change in the methodology. It feeds the next SDLC cycle, not blame.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('509bc5ff-86a6-59b6-aec8-3ea1e485a6fc', 6, 'mcq', 13, 'Who should <b>sign off the migrated data</b> before go-live?', NULL, '{"options": ["The software vendor''s sales team", "Business owners (finance, stores, sales) after reconciling control totals", "The IT intern who ran the scripts", "No one — the system validates itself"]}'::jsonb, '{"value": "B"}'::jsonb, 'Data belongs to the business. IT executes migration, but business owners must reconcile control totals and balances — it is their ledger that will be wrong otherwise.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('509bc5ff-86a6-59b6-aec8-3ea1e485a6fc', 7, 'mcq', 15, 'Which statement about <b>the old system''s availability</b> at cutover is correct?', NULL, '{"options": ["It should have been decommissioned the same night regardless", "Keeping it operational as a fallback until the new system stabilises is a legitimate parallel-running safeguard", "Old systems must always be destroyed for security", "Fallback plans are only for banks"]}'::jsonb, '{"value": "B"}'::jsonb, 'Because the old system was functional and its data extractable, it could have served as the safety net during parallel running. Premature decommissioning removed the only fallback.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('ecf5fa58-096a-54b3-840f-8f757568a46c', 1, 'mcq', 13, 'The maximum data the union can lose if it restores from the 02:00 backup — its <b>recovery point objective</b> — is:', NULL, '{"options": ["30 minutes", "15.5 hours of entries", "24 hours", "Nothing — backups are instant"]}'::jsonb, '{"value": "B"}'::jsonb, 'RPO is bounded by the backup interval: everything keyed between 02:00 and the 17:30 attack (15.5 hours) exists only on the encrypted server. The 24-hour figure is the RTO, a different concept.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('ecf5fa58-096a-54b3-840f-8f757568a46c', 2, 'mcq', 13, 'Why did having backups <b>not</b> protect the union?', NULL, '{"options": ["Backups were encrypted too, because the backup drive was attached to the same server and reachable by the ransomware", "Backups only work on Sundays", "The backup software was too old to hold milk data", "Backups are a detective control"]}'::jsonb, '{"value": "A"}'::jsonb, 'A backup that the attacker can reach and encrypt is not a backup. Backups must be offline, immutable or off-site so ransomware cannot destroy the copy it is meant to survive.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('ecf5fa58-096a-54b3-840f-8f757568a46c', 3, 'dnd', 16, 'Classify each control as <b>preventive</b>, <b>detective</b> or <b>corrective</b>.', NULL, '{"items": [{"id": "a", "text": "Attachment sandboxing that detonates suspicious files safely"}, {"id": "b", "text": "Intrusion-detection alerts when encryption behaviour starts"}, {"id": "c", "text": "Restoring the server from an offline backup"}, {"id": "d", "text": "Endpoint monitoring that flags mass file changes in minutes"}], "zones": {"prev": "Preventive", "det": "Detective", "corr": "Corrective"}}'::jsonb, '{"placement": {"a": "prev", "b": "det", "c": "corr", "d": "det"}}'::jsonb, 'Sandboxing stops the malware landing; IDS and endpoint monitoring spot it fast; restoration puts the business back. A complete defence needs all three families.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('ecf5fa58-096a-54b3-840f-8f757568a46c', 4, 'multi', 14, 'Which <b>two</b> should be the data-governance council''s first actions?', NULL, '{"options": ["Assign named data owners (e.g., a farmer-master-data steward)", "Approve a retention and protection policy for farmer and payout data", "Buy larger monitors", "Discontinue backups to save cost", "Share passwords so any clerk can recover data"]}'::jsonb, '{"values": [0, 1]}'::jsonb, 'Ownership and policy come first in governance: someone must be accountable for the data''s quality and protection before tooling decisions mean anything.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('ecf5fa58-096a-54b3-840f-8f757568a46c', 5, 'mcq', 13, 'The <b>first step</b> of the incident response, on discovering live ransomware, is to:', NULL, '{"options": ["Pay the ransom immediately", "Isolate affected systems from the network to stop the spread", "Delete all backups", "Announce the breach on social media"]}'::jsonb, '{"value": "B"}'::jsonb, 'Containment first: disconnect or shut down affected systems so encryption stops spreading, then eradicate, recover and notify. Paying first rewards the attacker and does not restore data.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('ecf5fa58-096a-54b3-840f-8f757568a46c', 6, 'mcq', 14, 'The union''s backups ran successfully every night for a year — yet recovery is <b>not assured</b>. Why must backups be tested by performing trial restores?', NULL, '{"options": ["Backups can fail silently — media faults, corrupted files or missed data may only surface when a restore is attempted", "Testing is only required for cloud backups", "Trial restores slow the backup job down", "Testing replaces the need for a recovery plan"]}'::jsonb, '{"value": "A"}'::jsonb, 'A backup job''s success message only means the copy ran, not that the data is intact or complete. An untested backup is a hope, not a control — restores must be rehearsed and timed against the RTO so the real recovery is not the first attempt.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('ecf5fa58-096a-54b3-840f-8f757568a46c', 7, 'mcq', 15, 'The union''s <b>data-governance council</b> should first establish:', NULL, '{"options": ["A policy that farmers must hand-deliver paper records", "Named data ownership (e.g., a farmer-payout data steward) and a data-classification/protection policy before any tooling decisions", "A new ERP vendor shortlist", "A social media account for incident updates"]}'::jsonb, '{"value": "B"}'::jsonb, 'Governance starts with accountability and policy: who owns each data domain, what protection each class of data requires. Tools and vendors implement policy — they cannot substitute for it.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('e2a2d5ec-48b1-54a0-9abc-845504f1d1fc', 1, 'num', 13, 'Calculate the <b>base forecast</b> of next quarter''s orders from the regression, in thousand units.', NULL, '{}'::jsonb, '{"value": 240}'::jsonb, '120 + 2.4 × 50 = 120 + 120 = 240 thousand units before seasonality.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('e2a2d5ec-48b1-54a0-9abc-845504f1d1fc', 2, 'num', 14, 'Apply the <b>Diwali-quarter seasonal uplift</b> and calculate the adjusted forecast, in thousand units (one decimal place).', NULL, '{}'::jsonb, '{"value": 268.8}'::jsonb, '240 × 1.12 = 268.8 thousand units. Seasonal indices adjust a base forecast for repeating calendar effects.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('e2a2d5ec-48b1-54a0-9abc-845504f1d1fc', 3, 'mcq', 13, 'The model''s R² of 0.64 means:', NULL, '{"options": ["64% of orders are explained by season", "64% of the variation in monthly orders is explained by variation in the retail index", "The forecast is 64% accurate", "The correlation coefficient is 0.64"]}'::jsonb, '{"value": "B"}'::jsonb, 'R² is the share of variance in the dependent variable explained by the model. The other statements confuse R² with accuracy, seasonality or the correlation coefficient.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('e2a2d5ec-48b1-54a0-9abc-845504f1d1fc', 4, 'dnd', 16, 'Match each observation to its <b>time-series component</b>.', NULL, '{"items": [{"id": "a", "text": "Orders have grown ~4% a year for five years"}, {"id": "b", "text": "Orders always jump in the Diwali quarter"}, {"id": "c", "text": "Orders dipped during a two-year overseas recession"}, {"id": "d", "text": "A dock strike cut one quarter''s shipments sharply"}], "zones": {"trend": "Trend", "seas": "Seasonal", "cyc": "Cyclical", "irr": "Irregular"}}'::jsonb, '{"placement": {"a": "trend", "b": "seas", "c": "cyc", "d": "irr"}}'::jsonb, 'Long-run growth is trend; fixed-calendar repeats are seasonal; multi-year business-cycle swings are cyclical; one-off shocks are irregular.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('e2a2d5ec-48b1-54a0-9abc-845504f1d1fc', 5, 'multi', 14, 'Which <b>two</b> steps would most strengthen the analyst''s defence of the forecast?', NULL, '{"options": ["Validating the model on months it was not fitted on", "Checking residuals for patterns the model misses", "Raising the seasonal uplift until the answer pleases the director", "Fitting on only the best three months", "Removing the intercept because it looks large"]}'::jsonb, '{"values": [0, 1]}'::jsonb, 'Out-of-sample validation and residual diagnosis are the standard checks on a regression forecast. Tuning assumptions to please, cherry-picking months and dropping the intercept all destroy the model''s integrity.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('e2a2d5ec-48b1-54a0-9abc-845504f1d1fc', 6, 'mcq', 13, 'The strongest <b>limitation</b> of basing orders on the retail index is:', NULL, '{"options": ["Regression cannot use whole numbers", "The relationship is correlational — a structural shift (e.g., a major client switching suppliers) can break it outside historical ranges", "R² must exceed 0.9 to be usable", "Seasonal adjustments are not allowed in exports"]}'::jsonb, '{"value": "B"}'::jsonb, 'Regression extrapolates a historical association; it cannot anticipate structural change or relationships outside the observed range. That is why forecasts are defended with validation and sensitivity analysis, not just R².');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('e2a2d5ec-48b1-54a0-9abc-845504f1d1fc', 7, 'mcq', 15, 'Before committing yarn volumes, the commercially sound use of the model is to:', NULL, '{"options": ["Commit exactly 268,800 units of yarn", "Use the forecast as a central estimate with sensitivity ranges, and stage purchases where yarn lead-times allow", "Ignore the model and buy last year''s volumes", "Double the forecast for safety"]}'::jsonb, '{"value": "B"}'::jsonb, 'Forecasts are planning inputs, not certainties: a central estimate, tested upside/downside, with staged commitments, dominates both blind trust and ignoring the model.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('26e94547-0a72-58bd-b047-ebe3ec2c4fe1', 1, 'mcq', 13, 'Sharing the client''s expansion cities with his friend would be:', NULL, '{"options": ["Acceptable — no documents change hands", "A breach of confidentiality: information acquired in a confidential relationship stays confidential however it is carried", "Acceptable if the friend promises discretion", "Required by the competence principle"]}'::jsonb, '{"value": "B"}'::jsonb, 'Confidentiality attaches to the information, not the medium. Verbal leakage of a client pipeline is every bit as much a breach as handing over files.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('26e94547-0a72-58bd-b047-ebe3ec2c4fe1', 2, 'mcq', 13, 'The weekend project on <b>pricing engines</b> is acceptable only if:', NULL, '{"options": ["It pays well", "Arun uses his general professional skills without disclosing or using his employer''s or client''s confidential information, and any conflict is disclosed per policy", "He works under a friend''s name", "His employer never finds out"]}'::jsonb, '{"value": "B"}'::jsonb, 'General skills are a professional''s own; confidential methods and client information are not. Disclosure and clearance under the conflict clause come first.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('26e94547-0a72-58bd-b047-ebe3ec2c4fe1', 3, 'multi', 14, 'Which <b>two</b> actions would clearly breach Arun''s obligations?', NULL, '{"options": ["Emailing himself the pricing-methodology documents ''for reference''", "Telling the consultancy he cannot share his employer''s proprietary methods", "Replying to the friend with the city list over coffee", "Disclosing the weekend project to his manager before accepting", "Asking HR how the conflict clause applies"]}'::jsonb, '{"values": [0, 2]}'::jsonb, 'Exfiltrating employer documents and verbally leaking client plans are both confidentiality breaches, documents or not. The other three are compliant conduct.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('26e94547-0a72-58bd-b047-ebe3ec2c4fe1', 4, 'list', 14, 'Match each disclosure situation to whether it is <b>permitted</b>.', NULL, '{"fields": [{"label": "A regulator''s lawful information request, handled through counsel", "options": ["Permitted", "Prohibited"]}, {"label": "Answering the friend''s curiosity about client plans", "options": ["Permitted", "Prohibited"]}]}'::jsonb, '{"values": ["Permitted", "Prohibited"]}'::jsonb, 'Legal compulsion is the recognised exception to confidentiality, handled properly through counsel. Curiosity creates no exception at all.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('26e94547-0a72-58bd-b047-ebe3ec2c4fe1', 5, 'mcq', 13, 'Arun''s confidentiality duty to his client <b>after he leaves the firm</b>:', NULL, '{"options": ["Ends with his last day", "Continues — the duty is not time-bound and survives employment", "Lasts one year only", "Applies only if he signed a fresh NDA"]}'::jsonb, '{"value": "B"}'::jsonb, 'The IMA confidentiality standard carries no expiry date: information acquired in a confidential relationship stays confidential after the relationship ends.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('26e94547-0a72-58bd-b047-ebe3ec2c4fe1', 6, 'dnd', 16, 'Match each piece of knowledge to how Arun may treat it.', NULL, '{"items": [{"id": "a", "text": "General valuation modelling skill"}, {"id": "b", "text": "Client''s expansion-city pipeline"}, {"id": "c", "text": "Employer''s proprietary pricing methodology"}, {"id": "d", "text": "Published quick-commerce market reports"}], "zones": {"own": "May use anywhere", "conf": "Must keep confidential"}}'::jsonb, '{"placement": {"a": "own", "b": "conf", "c": "conf", "d": "own"}}'::jsonb, 'Portable skill and public information are his to use; client pipelines and employer methods are confidential and survive his employment.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('26e94547-0a72-58bd-b047-ebe3ec2c4fe1', 7, 'mcq', 15, 'Before accepting the weekend project, the <b>first</b> step under the IMA resolution framework is:', NULL, '{"options": ["Accept first, disclose if asked", "Follow his employer''s established conflict-of-interest policy and disclose the engagement", "Refuse all side work permanently", "Ask the friend to decide for him"]}'::jsonb, '{"value": "B"}'::jsonb, 'The framework starts with the organisation''s own established policies. Disclosure lets the employer manage the conflict; silent acceptance converts a manageable conflict into a breach.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('2ff72a52-c47c-5703-99d5-76b89c9d17d8', 1, 'mcq', 13, 'Deferring a known warranty accrual to hit the covenant primarily violates the principle of:', NULL, '{"options": ["Competence", "Confidentiality", "Credibility", "Integrity only"]}'::jsonb, '{"value": "C"}'::jsonb, 'Credibility requires fair, objective, complete reporting and disclosure of all information that could influence a lender''s understanding. Suppressing a known liability misleads exactly the user the statements are for.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('2ff72a52-c47c-5703-99d5-76b89c9d17d8', 2, 'num', 14, 'Calculate the quarterly <b>warranty accrual</b> that Meera''s analysis supports (₹ lakh).', NULL, '{}'::jsonb, '{"value": 100}'::jsonb, '2.5% × ₹4,000 lakh = ₹100 lakh. This is the amount the CFO proposes to defer — it is estimable, supportable and therefore required.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('2ff72a52-c47c-5703-99d5-76b89c9d17d8', 3, 'num', 13, 'Using the exhibit figures, calculate what the <b>true current ratio</b> is once the deferred accrual (₹100 lakh) and stretched payables (₹50 lakh) are recognised (two decimals).', NULL, '{"decimals": true}'::jsonb, '{"value": 1.35}'::jsonb, 'Adjusted current liabilities = 3,000 + 100 + 50 = 3,150. Ratio = 4,260 ÷ 3,150 = 1.35 (1.3524). The covenant breach is real and the CFO''s proposal cannot print it away.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('2ff72a52-c47c-5703-99d5-76b89c9d17d8', 4, 'mcq', 13, 'The CFO''s ''fix it next quarter'' argument fails because:', NULL, '{"options": ["Next quarter is too far away to think about", "Quarterly statements must fairly present each period; deferring a known liability makes this period misleading regardless of later correction", "Covenants only matter annually", "Warranty costs are never material"]}'::jsonb, '{"value": "B"}'::jsonb, 'Each reporting period stands on its own. A deliberately misleading quarter cannot be laundered by a promised correction, and lenders rely on each set of statements as fairly presented.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('2ff72a52-c47c-5703-99d5-76b89c9d17d8', 5, 'multi', 14, 'Which <b>two</b> does the credibility principle require of Meera''s reporting?', NULL, '{"options": ["Disclosing the underlying collections problem to those who rely on the statements", "Stating the key assumptions behind her ratio projections", "Delaying disclosure until the covenant is safely met", "Presenting only the adjustments the CFO prefers", "Omitting the sensitivity of the ratio to the warranty policy"]}'::jsonb, '{"values": [0, 1]}'::jsonb, 'Credibility means fair, complete, objective communication: the real liquidity problem and the assumptions behind the numbers belong in front of users, not behind them.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('2ff72a52-c47c-5703-99d5-76b89c9d17d8', 6, 'mcq', 13, 'Meera''s correct first step under the IMA resolution framework is to:', NULL, '{"options": ["Quietly comply", "Present the facts and the covenant arithmetic to the CFO and follow the company''s established reporting policies", "Email the bank immediately", "Resign the same day"]}'::jsonb, '{"value": "B"}'::jsonb, 'Start inside the organisation: documented, factual escalation through established channels. External disclosure or resignation comes only if internal routes fail — or the conduct is clearly illegal.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('2ff72a52-c47c-5703-99d5-76b89c9d17d8', 7, 'mcq', 15, 'If, after escalation, the CFO insists on the misleading statements and the audit committee will not act, the IMA framework''s final internal step before resignation is to:', NULL, '{"options": ["Comply and move on", "Seek guidance from the IMA ethics committee, then — if unresolved — resign and submit a memorandum", "Leaks to the press", "Destroy her working papers"]}'::jsonb, '{"value": "B"}'::jsonb, 'The sequence is policies → chain of authority → ethics guidance → resignation with a memorandum if all internal avenues fail. Leaking or destroying records is never part of the framework.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('6171678a-7ba0-5d0e-9891-482dcfb20fa3', 1, 'mcq', 13, 'Paying the 15% fee as structured would primarily violate:', NULL, '{"options": ["Only internal expense policy", "The integrity principle and anti-bribery law — illegal payments are prohibited regardless of local custom or commercial importance", "The competence principle", "Nothing, if the fee is invoiced as consulting"]}'::jsonb, '{"value": "B"}'::jsonb, 'Integrity requires abstaining from conduct that would discredit the profession, and bribery — however labelled, and however customary locally — is illegal in most jurisdictions and always unethical. Relabelling does not cleanse it.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('6171678a-7ba0-5d0e-9891-482dcfb20fa3', 2, 'multi', 14, 'Which <b>two</b> are classic red flags in this proposal?', NULL, '{"options": ["Commission far above market rate", "Refusal to sign compliance certifications or describe deliverables", "Payment to an offshore account", "All of the above — and the agent''s explicit hint about officials", "A three-year contract term"]}'::jsonb, '{"values": [0, 1]}'::jsonb, 'Inflated fees, refusal of compliance paperwork, opaque offshore routing and explicit hints about officials are the textbook corruption red flags. Contract length is commercially neutral.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('6171678a-7ba0-5d0e-9891-482dcfb20fa3', 3, 'dnd', 16, 'Match each finding to the <b>required action</b>.', NULL, '{"items": [{"id": "a", "text": "Agent refuses due-diligence certification"}, {"id": "b", "text": "Official requests a personal payment to ''expedite'' a routine approval"}, {"id": "c", "text": "Standard, documented 5% commission to a certified agent"}, {"id": "d", "text": "Request to route fees offshore without documentation"}], "zones": {"no": "Do not proceed as proposed", "ok": "May proceed with controls", "no2": "Do not proceed as proposed", "no3": "Do not proceed as proposed"}}'::jsonb, '{"placement": {"a": "no", "b": "no2", "c": "ok", "d": "no3"}}'::jsonb, 'Anything undocumented, offshore, certification-refusing or payable to officials stops the deal. A market-rate, documented, certified commission with real deliverables can proceed under anti-corruption controls.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('6171678a-7ba0-5d0e-9891-482dcfb20fa3', 4, 'num', 13, 'Calculate the <b>excess</b> of the agent''s fee over a market-rate commission, as a percentage of contract value.', NULL, '{}'::jsonb, '{"value": 10}'::jsonb, '15% requested − 5% market = 10 percentage points of contract value — ₹2 crore of unexplained premium on a ₹20 crore deal, which is precisely where bribes hide.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('6171678a-7ba0-5d0e-9891-482dcfb20fa3', 5, 'mcq', 13, '''Everyone does it here'' is:', NULL, '{"options": ["A valid ethical defence", "Irrelevant — legality and the IMA standards do not bend to local convention", "Proof the payment is lawful", "A reason to increase the fee"]}'::jsonb, '{"value": "B"}'::jsonb, 'Ethical standards and anti-bribery law are not local customs. ''Everyone does it'' has never converted a bribe into a business expense.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('6171678a-7ba0-5d0e-9891-482dcfb20fa3', 6, 'list', 14, 'Match each <b>anti-corruption control</b> to what it does.', NULL, '{"fields": [{"label": "Anti-corruption clause with audit rights in the agent contract", "options": ["Deters and detects improper payments", "Guarantees winning the bid", "Replaces the need for due diligence", "Hides fees offshore"]}, {"label": "Documented due diligence before engaging the agent", "options": ["Verifies identity, reputation and deliverables before commitment", "Deters and detects improper payments", "Sets the commission rate", "Eliminates all legal risk permanently"]}]}'::jsonb, '{"values": ["Deters and detects improper payments", "Verifies identity, reputation and deliverables before commitment"]}'::jsonb, 'Contract clauses create deterrence and audit access; due diligence verifies who the counterparty is before money flows. Neither wins bids nor replaces the other.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('6171678a-7ba0-5d0e-9891-482dcfb20fa3', 7, 'mcq', 15, 'If refusing the fee means losing the contract, the IMA-compliant position is:', NULL, '{"options": ["Pay it — shareholder value comes first", "Refuse: no commercial outcome justifies illegal or unethical conduct; escalate and document the decision", "Pay half as a compromise", "Let the agent decide what is ethical"]}'::jsonb, '{"value": "B"}'::jsonb, 'Integrity is not negotiable against revenue. The professional''s duty is to refuse, escalate through established channels, and document — the loss of a tainted contract is not the accountant''s ethical failure.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('92352e87-b0b0-55f4-8901-69257efacdac', 1, 'mcq', 13, 'Finding 1 (hiring without checks, chronic turnover) belongs to which COSO component?', NULL, '{"options": ["Risk assessment", "Control environment", "Control activities", "Monitoring"]}'::jsonb, '{"value": "B"}'::jsonb, 'The control environment is the foundation: integrity, ethical values, competence and personnel policies. Careless hiring in a cash-handling role and chronic turnover are tone-at-the-top and people issues, not process design issues.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('92352e87-b0b0-55f4-8901-69257efacdac', 2, 'dnd', 16, 'Place each finding in its <b>COSO component</b>.', NULL, '{"items": [{"id": "a", "text": "New payments channel launched with no fraud-risk assessment"}, {"id": "b", "text": "Credit limits not enforced by the order-entry system"}, {"id": "c", "text": "Exception reports reach management three weeks late"}, {"id": "d", "text": "Prior-year audit findings never followed up"}, {"id": "e", "text": "Cashiers hired without reference checks"}], "zones": {"ce": "Control environment", "ra": "Risk assessment", "ca": "Control activities", "ic": "Information & communication", "mon": "Monitoring"}}'::jsonb, '{"placement": {"a": "ra", "b": "ca", "c": "ic", "d": "mon", "e": "ce"}}'::jsonb, 'Unassessed new risk = risk assessment; an unenforced policy = control activities; late reporting = information & communication; unfollowed findings = monitoring; personnel standards = control environment.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('92352e87-b0b0-55f4-8901-69257efacdac', 3, 'num', 13, 'Calculate the <b>sample deviation rate</b> from the credit-approval test, as a percentage (one decimal place).', NULL, '{"decimals": true}'::jsonb, '{"value": 5.0}'::jsonb, '3 deviations ÷ 60 transactions = 5.0%. The tolerable rate is 4%, so the observed rate exceeds tolerable and the auditor cannot rely on the control.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('92352e87-b0b0-55f4-8901-69257efacdac', 4, 'mcq', 13, 'The same clerk receives courier COD cash, records the receipts and updates customer ledgers. This primarily violates:', NULL, '{"options": ["Adequate documentation", "Segregation of duties", "Independent verification", "Physical safeguards"]}'::jsonb, '{"value": "B"}'::jsonb, 'One person holds custody of cash, records the transaction and maintains the ledger — the classic combination that lets errors or theft hide. Custody, recording and authorisation should be separated.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('92352e87-b0b0-55f4-8901-69257efacdac', 5, 'multi', 14, 'Which <b>two</b> of the following are control <b>activities</b>?', NULL, '{"options": ["Credit approvals by designated authority before dispatch", "Monthly bank reconciliations prepared by someone independent of cash custody", "A published code of conduct signed at induction", "The board''s risk appetite statement", "Periodic review of open audit findings"]}'::jsonb, '{"values": [0, 1]}'::jsonb, 'Authorisation and reconciliation are control activities — specific policies and procedures. The code of conduct and risk appetite are control environment; follow-up of findings is monitoring.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('92352e87-b0b0-55f4-8901-69257efacdac', 6, 'list', 14, 'Classify each situation as a <b>design deficiency</b> or an <b>operating deficiency</b>.', NULL, '{"fields": [{"label": "No bank reconciliation is ever prepared — the control does not exist", "options": ["Design deficiency", "Operating deficiency"]}, {"label": "Reconciliations are prepared, but the preparer signs them off without actually checking", "options": ["Design deficiency", "Operating deficiency"]}]}'::jsonb, '{"values": ["Design deficiency", "Operating deficiency"]}'::jsonb, 'A missing control is a design failure. A control that exists but is not performed with care is an operating failure — the remedy differs: design needs a new control, operating needs supervision and consequences.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('92352e87-b0b0-55f4-8901-69257efacdac', 7, 'mcq', 15, 'In a small branch where full segregation is impossible, the strongest <b>compensating control</b> is:', NULL, '{"options": ["Accepting the risk silently", "Independent review by the branch manager of daily cash counts, bank statements and reconciliations", "Removing all cash controls", "Rotating clerks every ten years"]}'::jsonb, '{"value": "B"}'::jsonb, 'Where duties cannot be separated, independent oversight restores the checking function: a reviewer without custody or recording duties examines the evidence regularly. Silent acceptance is not a control.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('51affae8-d0ab-5301-ac9c-95cffe4a8062', 1, 'dnd', 16, 'Classify each control as a <b>general control</b> or an <b>application control</b>.', NULL, '{"items": [{"id": "a", "text": "ERP edit check rejects negative invoice quantities"}, {"id": "b", "text": "Quarterly user-access reviews by the IT manager"}, {"id": "c", "text": "Duplicate vendor-master creation blocked by the system"}, {"id": "d", "text": "Change tickets approved before code moves to production"}, {"id": "e", "text": "Nightly backup job with off-site copy"}], "zones": {"gen": "General control", "app": "Application control"}}'::jsonb, '{"placement": {"a": "app", "b": "gen", "c": "app", "d": "gen", "e": "gen"}}'::jsonb, 'Edit checks inside a program are application controls. Access reviews, change management and backup discipline apply across all systems — they are general (ITGC) controls that create the environment application controls depend on.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('51affae8-d0ab-5301-ac9c-95cffe4a8062', 2, 'mcq', 13, 'The developer who can code, self-approve and deploy to production creates the greatest risk of:', NULL, '{"options": ["Slow report printing", "Unauthorised or untested changes entering production, with no independent check — and fraud concealed the same way", "Higher software licence fees", "Poor keyboard ergonomics"]}'::jsonb, '{"value": "B"}'::jsonb, 'Combining development, approval and deployment destroys the change-control chain: no one else sees the code or the business case. Errors and deliberate back doors both pass straight into the live system.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('51affae8-d0ab-5301-ac9c-95cffe4a8062', 3, 'num', 13, 'Calculate the <b>percentage of user accounts that are dormant</b> (one decimal place).', NULL, '{"decimals": true}'::jsonb, '{"value": 2.5}'::jsonb, '12 dormant ÷ 480 total = 2.5%. Dormant accounts are live attack surface — they should be disabled and re-provisioned on request.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('51affae8-d0ab-5301-ac9c-95cffe4a8062', 4, 'mcq', 13, 'The strongest control over <b>program changes</b> is:', NULL, '{"options": ["Faster deployment pipelines", "Independent approval and testing of each change before production release, with developer access to production removed", "Verbal sign-off from the developer''s manager", "Deploying only on weekends"]}'::jsonb, '{"value": "B"}'::jsonb, 'Change control means segregation between the person who writes code, the person who approves the business case and the person who releases it — plus documented testing. Speed and timing are irrelevant to the control objective.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('51affae8-d0ab-5301-ac9c-95cffe4a8062', 5, 'multi', 14, 'Which <b>two</b> are <b>preventive</b> IT controls?', NULL, '{"options": ["Multi-factor authentication on remote access", "Automatic disabling of accounts idle for 30 days", "Reviewing security logs every Monday", "Reconciling user lists against HR joiners and leavers monthly", "Investigating a reported phishing email"]}'::jsonb, '{"values": [0, 1]}'::jsonb, 'MFA and auto-disabling stop the event before it happens — preventive. Log review, access reconciliation and phishing investigation detect or respond after the fact.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('51affae8-d0ab-5301-ac9c-95cffe4a8062', 6, 'list', 14, 'Match each <b>control objective</b> to the control that serves it.', NULL, '{"fields": [{"label": "Keep branch data unreadable if network traffic is intercepted", "options": ["Encryption of data in transit", "Tested disaster-recovery site", "Segregation of duties in the ERP"]}, {"label": "Keep the ERP running if the primary server fails", "options": ["Encryption of data in transit", "Tested disaster-recovery site", "Segregation of duties in the ERP"]}]}'::jsonb, '{"values": ["Encryption of data in transit", "Tested disaster-recovery site"]}'::jsonb, 'Confidentiality on the wire is an encryption objective; continuity after failure is a recovery objective; segregation addresses authorisation and fraud, not traffic or uptime.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('51affae8-d0ab-5301-ac9c-95cffe4a8062', 7, 'mcq', 15, 'Which finding is a deficiency in <b>logical access</b> rather than physical or environmental control?', NULL, '{"options": ["The server room door is often propped open", "The ERP admin password is shared by three managers, so no action can be traced to a person", "There is no water sprinkler above the server rack", "The UPS battery has never been replaced"]}'::jsonb, '{"value": "B"}'::jsonb, 'Shared credentials defeat authentication and accountability — a logical-access failure. Propped doors, sprinklers and UPS batteries are physical/environmental controls.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('f067643e-6caf-5f81-b448-8d4f3990884c', 1, 'num', 13, 'Calculate the <b>gross margin percentage</b>.', NULL, '{}'::jsonb, '{"value": 40}'::jsonb, '(72,00,000 − 43,20,000) ÷ 72,00,000 = 28,80,000 ÷ 72,00,000 = 40%.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('f067643e-6caf-5f81-b448-8d4f3990884c', 2, 'num', 13, 'Calculate the <b>current ratio</b> (two decimals).', NULL, '{"decimals": true}'::jsonb, '{"value": 1.6}'::jsonb, '9,60,000 ÷ 6,00,000 = 1.6 — superficially comfortable.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('f067643e-6caf-5f81-b448-8d4f3990884c', 3, 'num', 13, 'Calculate the <b>quick ratio</b> (two decimals).', NULL, '{"decimals": true}'::jsonb, '{"value": 1.0}'::jsonb, '(9,60,000 − 3,60,000) ÷ 6,00,000 = 6,00,000 ÷ 6,00,000 = 1.0. Strip inventory and liquidity is exactly at par.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('f067643e-6caf-5f81-b448-8d4f3990884c', 4, 'num', 14, 'Calculate the <b>interest coverage ratio</b> (EBIT ÷ interest), in times.', NULL, '{}'::jsonb, '{"value": 3}'::jsonb, '9,00,000 ÷ 3,00,000 = 3.0× — below the industry''s 5×.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('f067643e-6caf-5f81-b448-8d4f3990884c', 5, 'num', 14, 'Using a 360-day year, calculate <b>days sales outstanding</b> (receivables ÷ sales × 360).', NULL, '{}'::jsonb, '{"value": 27}'::jsonb, '5,40,000 ÷ 72,00,000 × 360 = 27 days — collections are reasonably tight.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('f067643e-6caf-5f81-b448-8d4f3990884c', 6, 'num', 13, 'Calculate <b>inventory turnover</b> (COGS ÷ average inventory), in times.', NULL, '{}'::jsonb, '{"value": 6}'::jsonb, '43,20,000 ÷ 7,20,000 = 6×, versus the industry benchmark of about 9× — stock is moving slowly.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('f067643e-6caf-5f81-b448-8d4f3990884c', 7, 'mcq', 15, 'Which <b>overall credit view</b> best fits these numbers?', NULL, '{"options": ["Strong on every dimension — approve unconditionally", "Profitability is adequate and collections are tight, but the 1.0 quick ratio and 6× inventory turnover mean the current ratio leans on slow-moving stock, and 3× interest cover is thin", "Liquidity is superb — the current ratio settles everything", "The company must be loss-making"]}'::jsonb, '{"value": "B"}'::jsonb, 'Ratios must be read together: a 1.6 current ratio looks fine until the quick ratio shows it is entirely inventory-dependent, and that inventory turns at two-thirds the industry pace. Coverage adds a second soft spot. None of the figures shows losses — they show quality of the liquidity and thin debt-service headroom.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('9f460f95-e06c-5181-946c-93c247bc6e45', 1, 'num', 13, 'Calculate <b>SG&A as a percentage of sales</b>.', NULL, '{}'::jsonb, '{"value": 30}'::jsonb, '9,00,000 ÷ 30,00,000 = 30%.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('9f460f95-e06c-5181-946c-93c247bc6e45', 2, 'num', 14, 'Calculate how much <b>higher this year''s reported income is</b> because software was capitalised rather than expensed (₹).', NULL, '{}'::jsonb, '{"value": 1800000}'::jsonb, 'Expensing would have charged the full ₹24,00,000 this year. Capitalising charges only ₹6,00,000 of amortisation. Reported income is therefore ₹18,00,000 higher — a one-off policy benefit, not an operating improvement.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('9f460f95-e06c-5181-946c-93c247bc6e45', 3, 'mcq', 13, 'The year-end <b>bill-and-hold</b> sales are a red flag mainly because:', NULL, '{"options": ["Wholesale customers always pay late", "Revenue may be recorded before the earning process is complete — risks of reversal and channel stuffing", "Warehousing goods is expensive", "December sales are always fraudulent"]}'::jsonb, '{"value": "B"}'::jsonb, 'Bill-and-hold can be legitimate but is a classic vehicle for premature revenue: control and risks of ownership have not passed. A 40% December spike concentrated in one customer is precisely the pattern analysts probe.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('9f460f95-e06c-5181-946c-93c247bc6e45', 4, 'num', 14, 'Calculate the <b>cash conversion cycle</b> in days.', NULL, '{}'::jsonb, '{"value": 75}'::jsonb, 'DSO 45 + DIO 60 − DPO 30 = 75 days. Every rupee of working capital is tied up for 75 days before cash returns.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('9f460f95-e06c-5181-946c-93c247bc6e45', 5, 'dnd', 16, 'Classify each item''s treatment in the <b>indirect-method operating cash flow</b>.', NULL, '{"items": [{"id": "a", "text": "Amortisation of capitalised software"}, {"id": "b", "text": "Gain on sale of a delivery van"}, {"id": "c", "text": "Increase in inventory during the year"}, {"id": "d", "text": "Increase in accounts payable during the year"}], "zones": {"add": "Add to net income", "sub": "Subtract from net income"}}'::jsonb, '{"placement": {"a": "add", "b": "sub", "c": "sub", "d": "add"}}'::jsonb, 'Non-cash amortisation is added back; a gain (already in income but investing cash) is removed; inventory growth uses cash, payables growth provides it.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('9f460f95-e06c-5181-946c-93c247bc6e45', 6, 'mcq', 14, 'A <b>lengthening cash conversion cycle</b> alongside rising sales most directly signals:', NULL, '{"options": ["Improving cash discipline", "Profit is being recognised faster than cash is collected — earnings quality is deteriorating", "Suppliers are offering longer credit", "Inventory is shrinking"]}'::jsonb, '{"value": "B"}'::jsonb, 'When DSO and DIO rise while DPO falls, accounting profit outruns operating cash. Growing accruals with a stretched cycle is the signature of lower-quality earnings.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('9f460f95-e06c-5181-946c-93c247bc6e45', 7, 'mcq', 15, 'To compare this year with last on a like-for-like basis, the analyst should:', NULL, '{"options": ["Accept the capitalisation as fully comparable", "Normalise earnings by treating the software as an expense (reversing the ₹18,00,000 benefit) and re-examining the bill-and-hold revenue before drawing any growth conclusion", "Ignore working capital entirely", "Restate last year''s figures using the new policy with no further work"]}'::jsonb, '{"value": "B"}'::jsonb, 'Earnings quality analysis strips one-off policy effects and tests the recognition of revenue. Only after that reset does a year-on-year comparison mean anything.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('b233b7f8-c03a-525b-86f7-f696399a3ca5', 1, 'num', 13, 'Calculate the <b>payback period</b>, in years (one decimal place).', NULL, '{"decimals": true}'::jsonb, '{"value": 3.6}'::jsonb, '50,00,000 ÷ 14,00,000 = 3.6 years. The facilities head is right on this one number.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('b233b7f8-c03a-525b-86f7-f696399a3ca5', 2, 'mcq', 13, 'The 3.6048 factor is used here because the savings are:', NULL, '{"options": ["A single lump sum", "Equal annual amounts — an annuity", "Growing 5% a year", "Received only in year 5"]}'::jsonb, '{"value": "B"}'::jsonb, 'Equal, regular flows are discounted with the annuity factor, one multiplication instead of five. Uneven flows would need individual discounting.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('b233b7f8-c03a-525b-86f7-f696399a3ca5', 3, 'num', 14, 'Calculate the project''s <b>NPV</b> (₹ lakh, two decimals).', NULL, '{"decimals": true}'::jsonb, '{"value": 0.47}'::jsonb, 'PV of savings = 14,00,000 × 3.6048 = ₹50,46,720. NPV = 50,46,720 − 50,00,000 = ₹46,720 ≈ ₹0.47 lakh. Positive — accept on the numbers.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('b233b7f8-c03a-525b-86f7-f696399a3ca5', 4, 'mcq', 13, 'Because NPV at 12% is slightly positive, the project''s IRR must be:', NULL, '{"options": ["Exactly 12%", "Just above 12%", "Below 10%", "Above 25%"]}'::jsonb, '{"value": "B"}'::jsonb, 'IRR is the rate that drives NPV to zero. A positive NPV at 12% means the IRR sits just above 12% — the project only marginally clears the hurdle.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('b233b7f8-c03a-525b-86f7-f696399a3ca5', 5, 'mcq', 13, 'The deepest <b>limitation of the payback period</b> as used by the facilities head is that it:', NULL, '{"options": ["Is hard to compute", "Ignores the time value of money and everything that happens after payback", "Requires the cost in advance", "Cannot handle savings"]}'::jsonb, '{"value": "B"}'::jsonb, 'Payback says nothing about the cost of capital or the value created after the recovery point. It is a crude liquidity screen, not a value measure.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('b233b7f8-c03a-525b-86f7-f696399a3ca5', 6, 'multi', 14, 'Which <b>two</b> cash flows belong in the NPV calculation?', NULL, '{"options": ["The ₹14,00,000 annual electricity savings", "The ₹50,00,000 installation cost", "The ₹3,00,000 feasibility study already paid", "Allocated head-office rent that continues either way", "Depreciation of the panels as recorded in the ledger"]}'::jsonb, '{"values": [0, 1]}'::jsonb, 'Only incremental cash flows count. The study is sunk, allocated rent is unchanged by the decision, and depreciation is a non-cash allocation.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('b233b7f8-c03a-525b-86f7-f696399a3ca5', 7, 'mcq', 15, 'If savings were <b>uneven and riskier in later years</b>, the most defensible appraisal would be:', NULL, '{"options": ["Payback alone", "NPV with a risk-adjusted discount rate, plus scenario analysis — IRR can mislead with non-conventional flows", "Accounting rate of return", "Dividing cost by salvage"]}'::jsonb, '{"value": "B"}'::jsonb, 'Uneven flows break the annuity shortcut, and risk demands an explicit premium in the rate or in scenarios. NPV with sensitivity analysis stays the decision-grade method.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('97bd72f4-3a6c-5303-a23b-de8020e0d2d8', 1, 'num', 13, 'Calculate the <b>annual depreciation</b> on the new fleet (₹).', NULL, '{}'::jsonb, '{"value": 220000}'::jsonb, '(12,00,000 − 1,00,000 salvage) ÷ 5 = ₹2,20,000 per year.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('97bd72f4-3a6c-5303-a23b-de8020e0d2d8', 2, 'num', 13, 'Calculate the <b>annual after-tax cash inflow</b> from the savings (₹).', NULL, '{}'::jsonb, '{"value": 370000}'::jsonb, 'After-tax savings = 4,20,000 × (1 − 0.25) = ₹3,15,000. Depreciation tax shield = 2,20,000 × 0.25 = ₹55,000. Total = ₹3,70,000. Equivalently: 4,20,000 − 25% × (4,20,000 − 2,20,000).');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('97bd72f4-3a6c-5303-a23b-de8020e0d2d8', 3, 'num', 14, 'Calculate the project <b>NPV</b> (₹ lakh, two decimals).', NULL, '{"decimals": true}'::jsonb, '{"value": 2.65}'::jsonb, 'PV of inflows = 3,70,000 × 3.7908 = ₹14,02,596. PV of salvage = 1,00,000 × 0.6209 = ₹62,090. NPV = 14,02,596 + 62,090 − 12,00,000 = +₹2,64,686 ≈ ₹2.65 lakh.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('97bd72f4-3a6c-5303-a23b-de8020e0d2d8', 4, 'mcq', 13, 'Depreciation is added back to the after-tax saving in the cash-flow calculation because it is:', NULL, '{"options": ["A cash expense paid to the tax department", "A non-cash expense — only its tax shield affects cash", "A source of financing", "Ignored by the tax authorities"]}'::jsonb, '{"value": "B"}'::jsonb, 'Depreciation reduces taxable income but moves no cash. Its only cash effect is the tax saving, which the 3,70,000 already captures — so the expense itself must not be subtracted again.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('97bd72f4-3a6c-5303-a23b-de8020e0d2d8', 5, 'mcq', 14, 'The old fleet''s <b>original ₹8,00,000 cost</b> should be treated as:', NULL, '{"options": ["Deducted from the new project''s cost", "A sunk cost — irrelevant to the replacement decision", "Amortised against the savings", "Added to year-5 salvage"]}'::jsonb, '{"value": "B"}'::jsonb, 'Money spent on the old fleet cannot be recovered by any decision now. Only current and future incremental flows — new cost, savings, salvage — belong in the analysis.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('97bd72f4-3a6c-5303-a23b-de8020e0d2d8', 6, 'multi', 14, 'Which <b>two</b> cash flows are correctly included in this appraisal?', NULL, '{"options": ["The ₹12,00,000 installed cost at time zero", "The ₹1,00,000 salvage at the end of year 5", "The old fleet''s written-off ₹8,00,000", "Last year''s diesel repair bill", "The forklift supplier''s brochure cost"]}'::jsonb, '{"values": [0, 1]}'::jsonb, 'The outlay today and the salvage in year 5 are incremental future flows. Written-off cost and last year''s repairs are sunk; the brochure is noise.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('97bd72f4-3a6c-5303-a23b-de8020e0d2d8', 7, 'mcq', 15, 'If pre-tax savings fell by 10% to ₹3,78,000, the NPV would:', NULL, '{"options": ["Turn sharply negative", "Fall to roughly ₹1.45 lakh — still positive but with a much thinner margin", "Stay at ₹2.65 lakh", "Double"]}'::jsonb, '{"value": "B"}'::jsonb, 'New inflow = 3,78,000 × 0.75 + 55,000 = ₹3,38,500; × 3.7908 = ₹12,83,000 + 62,090 − 12,00,000 ≈ +₹1.45 lakh. The decision survives, but the cushion halves — exactly what sensitivity analysis exists to show.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('79e48838-d66b-51a6-91af-bb128ec4f709', 1, 'num', 13, 'Calculate the <b>flexible-budget operating income</b> at 55,000 boxes (₹).', NULL, '{}'::jsonb, '{"value": 380000}'::jsonb, '55,000 × (40 − 24) − 5,00,000 = 8,80,000 − 5,00,000 = ₹3,80,000.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('79e48838-d66b-51a6-91af-bb128ec4f709', 2, 'num', 13, 'Calculate the <b>static-budget operating income</b> (₹).', NULL, '{}'::jsonb, '{"value": 300000}'::jsonb, '50,000 × 16 − 5,00,000 = ₹3,00,000 — the plan the static comparison starts from.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('79e48838-d66b-51a6-91af-bb128ec4f709', 3, 'num', 14, 'Calculate the <b>sales-volume variance</b> in operating income (₹).', NULL, '{}'::jsonb, '{"value": 80000}'::jsonb, 'Flexible 3,80,000 − static 3,00,000 = ₹80,000 favourable: 5,000 extra boxes × ₹16 contribution each.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('79e48838-d66b-51a6-91af-bb128ec4f709', 4, 'num', 14, 'Calculate the <b>variable-cost spending variance</b> — flexible-budget variable cost minus actual (₹).', NULL, '{}'::jsonb, '{"value": 110000}'::jsonb, 'Flexible VC = 55,000 × 24 = ₹13,20,000. Actual ₹14,30,000. Variance = ₹1,10,000 unfavourable — costs ran over standard for the volume achieved.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('79e48838-d66b-51a6-91af-bb128ec4f709', 5, 'mcq', 13, 'The point of <b>flexing the budget</b> to actual volume is to:', NULL, '{"options": ["Make the budget look better", "Separate the volume effect from price and cost effects so managers are judged only on what they control", "Eliminate the need for standards", "Hide unfavourable variances"]}'::jsonb, '{"value": "B"}'::jsonb, 'A static comparison credits or blames managers for demand they did not create. Flexing re-bases the standard to actual volume, isolating spending and price performance.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('79e48838-d66b-51a6-91af-bb128ec4f709', 6, 'mcq', 14, 'Actual variable cost per box was ₹14,30,000 ÷ 55,000 = <b>₹26 against a ₹24 standard</b>. The most plausible explanation to investigate first is:', NULL, '{"options": ["A spreadsheet rounding error", "Ingredient price increases or wastage/overtime in production — a per-unit cost overrun of ₹2", "Fixed costs too low", "Too few boxes sold"]}'::jsonb, '{"value": "B"}'::jsonb, 'The variance is ₹2 per unit at the actual volume — a genuine unit-cost problem, not volume. Ingredient prices, recipe wastage and overtime premiums are the usual suspects in festival-season baking.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('79e48838-d66b-51a6-91af-bb128ec4f709', 7, 'mcq', 15, 'The correct reading of this quarter for the partner is:', NULL, '{"options": ["We beat budget — well done", "Volume delivered ₹80,000 more than planned, but cost overruns (₹1,10,000 variable + ₹10,000 fixed) took operating income ₹1,20,000 below the flexible budget — growth was bought inefficiently", "The bakery should stop flexible budgeting", "Fixed costs caused the whole shortfall"]}'::jsonb, '{"value": "B"}'::jsonb, 'The flexible budget says: at 55,000 boxes, income should have been ₹3,80,000; it was ₹2,60,000. The entire ₹1,20,000 gap is controllable cost performance — the volume win is real, but it was given back and more.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('7f4836b9-ed81-5bd3-bc42-47e7ac06a7b1', 1, 'num', 13, 'Calculate <b>December collections</b> (₹).', NULL, '{}'::jsonb, '{"value": 1120000}'::jsonb, '60% × 12,00,000 = 7,20,000 (December billings) + 40% × 10,00,000 = 4,00,000 (November billings) = ₹11,20,000.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('7f4836b9-ed81-5bd3-bc42-47e7ac06a7b1', 2, 'num', 13, 'Calculate <b>accounts receivable at 31 December</b> (₹).', NULL, '{}'::jsonb, '{"value": 480000}'::jsonb, '40% of December billings remain uncollected: 0.40 × 12,00,000 = ₹4,80,000. November billings are fully collected by 31 December.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('7f4836b9-ed81-5bd3-bc42-47e7ac06a7b1', 3, 'num', 14, 'Calculate the <b>ending cash balance</b> for December before any financing (₹).', NULL, '{}'::jsonb, '{"value": 150000}'::jsonb, '80,000 + 11,20,000 − 10,50,000 = ₹1,50,000.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('7f4836b9-ed81-5bd3-bc42-47e7ac06a7b1', 4, 'num', 13, 'Compare the ending balance with the ₹1,00,000 minimum: what is the <b>surplus</b> (₹)?', NULL, '{}'::jsonb, '{"value": 50000}'::jsonb, '1,50,000 − 1,00,000 = ₹50,000 above the floor — no borrowing is required in December.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('7f4836b9-ed81-5bd3-bc42-47e7ac06a7b1', 5, 'mcq', 13, 'A <b>cash budget</b> rather than the income statement drives this decision because:', NULL, '{"options": ["The income statement is illegal", "Survival depends on the timing of cash in and out, not on when revenue is earned", "Banks only read accrual statements", "It avoids showing losses"]}'::jsonb, '{"value": "B"}'::jsonb, 'Liquidity is a timing question. A business can be profitable on paper and still miss payroll — the cash budget maps when money actually arrives and leaves.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('7f4836b9-ed81-5bd3-bc42-47e7ac06a7b1', 6, 'mcq', 14, 'If December disbursements rise to ₹12,00,000, the budget shows cash of ₹0 — below the minimum. The <b>borrowing required</b> is:', NULL, '{"options": ["₹50,000", "₹1,00,000", "₹2,00,000", "Nothing — zero is fine"]}'::jsonb, '{"value": "B"}'::jsonb, 'Need 1,00,000 minimum − 0 available = ₹1,00,000; the credit line works in multiples of ₹50,000, so borrow ₹1,00,000 (interest ₹10,000 next month at 1%).');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('7f4836b9-ed81-5bd3-bc42-47e7ac06a7b1', 7, 'mcq', 15, 'The group replaces its fixed annual budget with a <b>rolling 12-month forecast</b> updated quarterly. The main advantage is:', NULL, '{"options": ["It removes the need to plan", "The planning horizon never expires, so seasonal patterns like the festival billing surge are always visible to lenders and management", "It guarantees profits", "It eliminates collections risk"]}'::jsonb, '{"value": "B"}'::jsonb, 'A rolling forecast keeps a constant forward window: each update drops the elapsed month and adds a new one ahead. Seasonal cash rhythms stay in view, and financing needs surface months earlier.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('840eeb83-ef9a-5a6d-b8e2-063ef9dd0445', 1, 'num', 13, 'Calculate <b>Division X''s ROI</b> (percentage).', NULL, '{}'::jsonb, '{"value": 20}'::jsonb, '18,00,000 ÷ 90,00,000 = 20%.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('840eeb83-ef9a-5a6d-b8e2-063ef9dd0445', 2, 'num', 13, 'Calculate <b>Division X''s residual income</b> (₹ lakh, two decimals).', NULL, '{"decimals": true}'::jsonb, '{"value": 7.2}'::jsonb, '18,00,000 − (12% × 90,00,000) = 18,00,000 − 10,80,000 = ₹7,20,000 = ₹7.2 lakh.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('840eeb83-ef9a-5a6d-b8e2-063ef9dd0445', 3, 'num', 14, 'Calculate the <b>project''s ROI</b> (percentage).', NULL, '{}'::jsonb, '{"value": 16}'::jsonb, '1,60,000 ÷ 10,00,000 = 16% — above the 12% minimum, below Division X''s current 20%.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('840eeb83-ef9a-5a6d-b8e2-063ef9dd0445', 4, 'mcq', 13, 'Under <b>residual income</b>, the eco-camp project would be:', NULL, '{"options": ["Rejected — it dilutes ROI", "Accepted — it adds ₹40,000 of residual income (1,60,000 − 12% × 10,00,000)", "Rejected — it is below the minimum return", "Sent back for a 20% return"]}'::jsonb, '{"value": "B"}'::jsonb, 'RI = 1,60,000 − 1,20,000 = +₹40,000. Any project above the hurdle adds RI, so a residual-income manager accepts what an ROI-maximising manager refuses — goal congruence restored.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('840eeb83-ef9a-5a6d-b8e2-063ef9dd0445', 5, 'mcq', 14, 'The <b>structural weakness of ROI</b> for divisional decisions is that it:', NULL, '{"options": ["Requires audited accounts", "Can reject projects that beat the company''s hurdle but dilute the division''s percentage — maximising the ratio is not maximising value", "Ignores assets", "Cannot be compared across years"]}'::jsonb, '{"value": "B"}'::jsonb, 'A ratio can be ''improved'' by shrinking the denominator. Managers measured on ROI rationally refuse value-adding projects below their current average — the classic divisional incentive failure.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('840eeb83-ef9a-5a6d-b8e2-063ef9dd0445', 6, 'dnd', 16, 'Match each <b>balanced-scorecard measure</b> to its perspective.', NULL, '{"items": [{"id": "a", "text": "Repeat-guest rate and review scores"}, {"id": "b", "text": "Revenue per available room (RevPAR) growth"}, {"id": "c", "text": "Percentage of staff multi-skilled in two roles"}, {"id": "d", "text": "Average check-in waiting time"}], "zones": {"fin": "Financial", "cust": "Customer", "proc": "Internal process", "learn": "Learning & growth"}}'::jsonb, '{"placement": {"a": "cust", "b": "fin", "c": "learn", "d": "proc"}}'::jsonb, 'Guests'' outcomes are customer measures; money outcomes are financial; process speed is internal; workforce capability is learning & growth.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('840eeb83-ef9a-5a6d-b8e2-063ef9dd0445', 7, 'mcq', 15, 'A recognised <b>weakness of residual income</b> that ROI does not share is that it:', NULL, '{"options": ["Cannot incorporate the hurdle rate", "Is an absolute rupee figure — not comparable across divisions of very different sizes", "Ignores profit", "Always matches tax accounts"]}'::jsonb, '{"value": "B"}'::jsonb, 'RI grows with division size, so big divisions look better even at mediocre returns. ROI''s percentage form is size-comparable; RI''s rupee form is decision-cleaner for a given division. Many firms watch both.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('dfe6a6ec-c247-5ec4-bb49-bcb6688c8e0c', 1, 'mcq', 13, 'The after-tax cost of debt is used in the WACC because:', NULL, '{"options": ["Banks demand it", "Interest is tax-deductible, so the government effectively subsidises part of the debt cost", "Equity is cheaper", "Debt has no risk"]}'::jsonb, '{"value": "B"}'::jsonb, 'Each rupee of interest saves 25 paise of tax. The true cost of a 9% loan is 9% × (1 − 0.25) = 6.75% — the tax shield is real cash kept.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('dfe6a6ec-c247-5ec4-bb49-bcb6688c8e0c', 2, 'num', 13, 'Calculate the <b>after-tax cost of debt</b> (percentage, two decimals).', NULL, '{"decimals": true}'::jsonb, '{"value": 6.75}'::jsonb, '9% × (1 − 0.25) = 6.75%.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('dfe6a6ec-c247-5ec4-bb49-bcb6688c8e0c', 3, 'num', 14, 'Calculate the company''s <b>WACC</b> (percentage, two decimals).', NULL, '{"decimals": true}'::jsonb, '{"value": 10.5}'::jsonb, '0.40 × 6.75% + 0.60 × 13% = 2.70% + 7.80% = 10.50%.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('dfe6a6ec-c247-5ec4-bb49-bcb6688c8e0c', 4, 'num', 13, 'By how many <b>percentage points</b> does the contract''s expected return clear the WACC (two decimals)?', NULL, '{"decimals": true}'::jsonb, '{"value": 1.0}'::jsonb, '11.5% − 10.5% = 1.0 percentage point of excess return — positive, but thin for a risky five-year commitment.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('dfe6a6ec-c247-5ec4-bb49-bcb6688c8e0c', 5, 'mcq', 14, 'The correct weights for the WACC are:', NULL, '{"options": ["Book values from the balance sheet", "Market-value weights reflecting today''s capital structure — financing at the margin", "Last decade''s average", "Whatever the bank suggests"]}'::jsonb, '{"value": "B"}'::jsonb, 'The WACC prices new money, so it must use current market proportions and current required returns. Book values are historical remnants that can diverge sharply from market.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('dfe6a6ec-c247-5ec4-bb49-bcb6688c8e0c', 6, 'multi', 14, 'Which <b>two</b> effects does raising the debt share have on the cost of capital?', NULL, '{"options": ["After-tax debt is cheaper than equity, so WACC initially falls", "Higher leverage raises financial risk, so shareholders demand a higher return — pushing the cost of equity up", "Interest becomes non-deductible", "WACC falls without limit as debt rises", "Equity becomes risk-free"]}'::jsonb, '{"values": [0, 1]}'::jsonb, 'Cheap after-tax debt pulls WACC down at moderate levels; rising financial risk pushes the cost of equity up at high levels. The trade-off is why capital structure matters — and why WACC is U-shaped.');
INSERT INTO public.cbq_tasks (case_id, seq, type, marks, prompt, hint, payload, answer, explanation) VALUES ('dfe6a6ec-c247-5ec4-bb49-bcb6688c8e0c', 7, 'mcq', 15, 'If the equipment were financed entirely with a new 9% loan, the correct evaluation rate is:', NULL, '{"options": ["9% — match the loan rate", "The marginal cost of capital for the project — the WACC within the target structure; the financing vehicle does not change the project''s risk or its opportunity cost", "13% — only equity counts", "0% — debt is free"]}'::jsonb, '{"value": "B"}'::jsonb, 'Project hurdle rates price risk, not funding tickets. Financing with debt does not make a risky project risk-free; below-target-structure financing mixes create their own problems. Evaluate at the marginal WACC.');
